    t[211407] = { name = "Книга Боба", fen = "The pages of this leather-bound book are yellowed with age, with many a dog-earred page.", fua = "Сторінки цієї книги в шкіряній палітурці пожовкли від часу, а багато з них загнуто на кутиках." }
    t[211412] = { name = "Співучий Камінь", fen = "This gem resonates with a harmony that is felt more than heard.", fua = "Цей самоцвіт резонує гармонією, яку радше відчуваєш, ніж чуєш." }
    t[211415] = { name = "Брила Сивкаменю", fen = "Pried from a vein of saturated ore, this sivstone is perfect for an opportunist who knows how to work with it.", fua = "Виламаний з насиченої рудної жили, цей сивкамінь ідеальний для спритника, що вміє з ним працювати." }
    t[211428] = { name = "Пожитки Земельника", fen = "Gems, body parts, and equipment that were broken off and looted from shutdown earthen.", fua = "Самоцвіти, частини тіла та спорядження, відламані й здобуті з вимкнених земельників." }
    t[211459] = { name = "Заряджений Магнетит", fen = "It tingles with a latent charge of electrical energy.", fua = "Він поколює прихованим зарядом електричної енергії." }
    t[211469] = "Чавильний Гак"
    t[211474] = { name = "Тіньоокий Групер", fen = "A strange sour tasting fish, but the frogs love them!", fua = "Дивна рибина з кислуватим присмаком, але жаби її обожнюють!" }
    t[211475] = { name = "Сутінкова Прянощі", fen = "A pinch of shadows and a dash of mystery.", fua = "Дрібка тіней і пучка таємниці." }
    t[211478] = "Темнокорінна Хурма"
    t[211479] = "Ікра з Жаб'ячим Поцілунком"
    t[211481] = { name = "Чоботи-Тупотуни", fen = "These Machine Speaker shoes can produce a massive stomp, causing (some) machinery to re-activate.", fua = "Ці чоботи Машинних Мовців здатні видати потужний тупіт, що знову вмикає (деякі) механізми." }
    t[211483] = "Шалена Піщана Кулька"
    t[211484] = "Шалена Водяна Кулька"
    t[211485] = { name = "Заряджений Стихією Мул", fen = "Faint energy courses through the silt.", fua = "Крізь мул струмує слабка енергія." }
    t[211489] = { name = "Величезна Грудка Вогняного Меду", fen = "Although unrefined, this enormous chunk of fire honey is extremely hot!", fua = "Хоч ця величезна грудка вогняного меду й неочищена, вона надзвичайно гаряча!" }
    t[211535] = { name = "Сувій Розтрощення", fen = "Thalassian script glitters across the parchment.", fua = "Таласійський напис мерехтить на пергаменті." }
    t[211769] = { name = "Накази з Облогової Тверджі", fen = "A torn fragment of an official document with letters that appear to have been burned instead of written, signed with the name Anub'azal.", fua = "Подертий уривок офіційного документа з літерами, які наче випалили, а не написали, підписаний іменем Ануб'азал." }
    t[211774] = { name = "Зім'ята Латна Рукавиця Лева", fen = "The reticulated pieces are bent and broken beyond repair.", fua = "З'єднані пластини зігнуті й поламані безнадійно." }
    t[211775] = { name = "Вибілені Кістки", fen = "Thankfully, none of these appear human. It seems unlikely that Anduin met his demise here.", fua = "На щастя, жодна з них не схожа на людську. Малоймовірно, що Андуїн знайшов тут свою смерть." }
    t[211776] = { name = "Вологий Ремонтний Набір", fen = "Odds are this repair kit barely worked in the first place, so how much worse could some water damage be?", fua = "Цей ремонтний набір і без того ледве працював, тож наскільки гіршим могло б його зробити трохи води?" }
    t[211783] = { name = "Клапоть Зношеної Тканини", fen = "Though it is but a scrap, the worn threads of this fabric seem familiar.", fua = "Хоч це лише клапоть, потерті нитки цієї тканини видаються знайомими." }
    t[211796] = { name = "Тавматургія", fen = "Attempt to perform a miracle with materials of your choosing.", fua = "Спробуйте здійснити диво з матеріалами на ваш вибір." }
    t[211801] = "Капелюшок Отруйного Гриба"
    t[211802] = { name = "Зловісний Трансмутаген", fen = "A mysterious byproduct of performing transmutations.", fua = "Загадковий побічний продукт виконання трансмутацій." }
    t[211803] = { name = "Мінливий Трансмутаген", fen = "A peculiar byproduct of performing transmutations.", fua = "Своєрідний побічний продукт виконання трансмутацій." }
    t[211804] = { name = "Нестабільний Трансмутаген", fen = "An unstable byproduct of performing transmutations.", fua = "Нестабільний побічний продукт виконання трансмутацій." }
    t[211805] = { name = "Осяйний Трансмутаген", fen = "A remarkable byproduct of performing transmutations.", fua = "Визначний побічний продукт виконання трансмутацій." }
    t[211806] = { name = "Позолочена Пляшечка", fen = "Purchased from tradeskill vendors. Jewelcrafters can also craft this item at equal or higher qualities. Can be bought and sold on the Auction House.", fua = "Купується в торговців ремісничими товарами. Ювеліри також можуть виготовити цей предмет рівної або вищої якості. Можна купувати й продавати на Аукціоні." }
    t[211807] = { name = "Позолочена Пляшечка", fen = "Jewelcrafters can craft this item at high qualities. Can be purchased from a vendor at lower quality. Can be bought and sold on the Auction House.", fua = "Ювеліри можуть створити цей предмет високої якості. Нижчу якість можна придбати в торговця. Можна купити й продати на Аукціоні." }
    t[211808] = { name = "Позолочена Пляшечка", fen = "Jewelcrafters can craft this item at high qualities. Can be purchased from a vendor at lower quality. Can be bought and sold on the Auction House.", fua = "Ювеліри можуть створити цей предмет високої якості. Нижчу якість можна придбати в торговця. Можна купити й продати на Аукціоні." }
    t[211811] = { name = "Невелика Грудка Вогняного Меду", fen = "The fire honey is way too hot to handle in your bare hands. Thankfully, you've got a jar!", fua = "Вогняний мед надто гарячий, щоб тримати його голими руками. На щастя, у вас є слоїк!" }
    t[211858] = { name = "Наелектризований Мохошерст", fen = "The coarse moss crackles with stored electrical energy.", fua = "Грубий мох потріскує від накопиченої електричної енергії." }
    t[211861] = { name = "Тіньовий Баклажан", fen = "A rare and unusual growth.", fua = "Рідкісний і незвичний плід." }
    t[211863] = { name = "Шкварчасте Ядро Магми", fen = "When shaped and carved, these dangerously hot cores can make for beautiful ornamentation.", fua = "Якщо їх обробити й вирізьбити, ці небезпечно гарячі ядра можуть стати чудовою оздобою." }
    t[211870] = { name = "Клинки Флінна", fen = "A pair of sea-weathered blades.", fua = "Пара клинків, обвітрених морем." }
    t[211872] = { name = "Дозорний Смолоскип", fen = "Its light instills hope in Arathi and fear in others.", fua = "Його світло вселяє надію в араті й страх в інших." }
    t[211878] = "Алґарійське Зілля Зцілення"
    t[211879] = "Алґарійське Зілля Зцілення"
    t[211880] = "Алґарійське Зілля Зцілення"
    t[211929] = { name = "Уламки в Іхорі", fen = "Slick, mucosal residue clings to the glass shards.", fua = "Слизький в'язкий осад чіпляється до скляних скалок." }
    t[211930] = { name = "Пошкоджений Каркас", fen = "Though bent out of shape, this framework carries lingering traces of warding magicks.", fua = "Хоч і скривлений, цей каркас досі береже залишки захисної магії." }
    t[211931] = "Ріг Закликача Безодні"
    t[211945] = { name = "Смолоскип Священного Полум'я", fen = "Lit with the holy flame of Arathor.", fua = "Запалений священним полум'ям Аратора." }
    t[211947] = { name = "Запас Насіння для Сівби", fen = "Seeds ready to be planted.", fua = "Насіння, готове до посадки." }
    t[211948] = { name = "Спис Кобісів", fen = "Kills Kobyss just as well as Arathi.", fua = "Убиває кобісів так само добре, як араті." }
    t[211958] = { name = "Ретельне Експериментування", fen = "Experiment with volatile reagents in hopes of discovering new recipes.", fua = "Експериментуйте з нестабільними реагентами в надії відкрити нові рецепти." }
    t[211959] = { name = "Загублені Пожитки", fen = "A collection of items formerly belonging to Andari, a Lamplighter who fell in the line of duty.", fua = "Збірка речей, що колись належали Андарі, ліхтарнику, який загинув при виконанні обов'язку." }
    t[211960] = "Ігрова Фігурка"
    t[211961] = { name = "Реактивний Ударний Гайковерт", fen = "Over-engineered and fit with a Goblin Industrial Standard drive bit. One part of a whole set.", fua = "Надміру складний, але має стандартну ґоблінську промислову насадку. Частина цілого набору." }
    t[211962] = { name = "Блискуча Руда", fen = "Streaks of ruby red shine through primarily slate rock. This ore is perfect for earthen refinement.", fua = "Рубіново-червоні прожилки проблискують крізь переважно сланцеву породу. Ця руда чудово підходить для вдосконалення земельників." }
    t[211963] = "Підметальник Стелі"
    t[211964] = { name = "Улов зі Стіллстоуна", fen = "Contains an assortment of fish caught in Stillstone Pond.", fua = "Містить добірку риби, спійманої в ставку Стіллстоун." }
    t[211966] = { name = "Запечатана Скриня Нерубіан", fen = "Mysterious crate not from these lands.", fua = "Загадкова скриня, наче не з цих земель." }
    t[211967] = { name = "Велика Запечатана Скриня", fen = "Large crate of missing goods.", fua = "Велика скриня з утраченими речами." }
    t[211968] = { name = "Стос Креслень", fen = "Missing blueprints and plans.", fua = "Загублені креслення та плани." }
    t[211969] = { name = "Замкнена Аратійська Скриня", fen = "Strong locks protect the valuables inside.", fua = "Міцні замки оберігають цінності всередині." }
    t[211970] = { name = "Вино Врожаю", fen = "Wine made from Hallowfall fruits.", fua = "Вино з фруктів Голловфолу." }
    t[211971] = { name = "Поліг Кукурудза", fen = "Harvested in the light of a keystone", fua = "Зібрана у світлі ключа." }
