    t[212529] = { name = "Спорові Голки", fen = "Once the rounded nubs have been removed from the spore spines, their tips are sharper than cut obsidian or diamond. Perfect for fine point etching of gemstones.", fua = "Коли з спорових голок зняти округлі нарости, їхні вістря стають гострішими за різьблений обсидіан чи діамант. Ідеальні для тонкого гравіювання самоцвітів." }
