    t[213000] = { name = "Святий Вогнеметний Смолоскип", fen = "Point this torch, twist the hilt, and watch a spew of holy fire engulf anyone you don't like. Can burn away nerubian webbing.", fua = "Наведіть цей смолоскип, поверніть руків'я й дивіться, як струмінь святого вогню поглинає кожного, хто вам не до вподоби. Здатен спалювати павутиння нерубів." }
    t[213085] = { name = "Загублений Скарб", fen = "There are some valuables in this chest, although it isn't exactly what you were promised at the start of this venture.", fua = "У цій скрині є дещо цінне, хоч і не зовсім те, що вам обіцяли на початку цієї пригоди." }
    t[213108] = { name = "Спаплюжена Олія", fen = "Thick and dark, almost like crude oil.", fua = "Густа й темна, майже як сира нафта." }
    t[213163] = { name = "Криптографічний Гліф", fen = "The rune carved into the stone seems to shimmer and change its shape as you lay eyes upon it.", fua = "Руна, вирізьблена в камені, ніби мерехтить і змінює форму, щойно ви скеровуєте на неї погляд." }
    t[213178] = { name = "Отрута Підземного Повзуна", fen = "Paralytic venom. Undercrawlers prefer to keep their prey alive.", fua = "Паралітична отрута. Підземні повзуни воліють тримати здобич живою." }
    t[213191] = { name = "Араттійська Кресальниця", fen = "Keep the Sacred Flame with you, everywhere you go.", fua = "Тримайте Священне Полум'я при собі, куди б ви не йшли." }
    t[213193] = { name = "Медальйон Араттійського Війська", fen = "Muck stains its polished surface", fua = "Його поліровану поверхню вкривають плями бруду." }
    t[213197] = { name = "Лотос Небуття", fen = "A rare herb that emanates a feeling of nothingness. Sometimes gathered by players with the Herbalism skill. Can be bought and sold on the Auction House.", fua = "Рідкісна трава, що випромінює відчуття небуття. Іноді збирається гравцями з навичкою Травництва. Можна купити та продати на Аукціоні." }
    t[213209] = { name = "Яйце Личинки", fen = "Warm and quivering. Probably a kobold delicacy.", fua = "Тепле й тремтливе. Мабуть, делікатес для кобольдів." }
    t[213218] = { name = "Отрута Королеви Рікітіки", fen = "A powerful antidote. In the right amounts.", fua = "Потужна протиотрута. У правильних дозах." }
    t[213219] = { name = "Подрібнені Самоцвіти", fen = "Acquired by Jewelcrafters by crushing Algari gems. Can be bought and sold on the Auction House.", fua = "Здобуваються ювелірами шляхом подрібнення алґарських самоцвітів. Можна купити та продати на Аукціоні." }
    t[213220] = { name = "Подрібнені Самоцвіти", fen = "Acquired by Jewelcrafters by crushing Algari gems. Can be bought and sold on the Auction House.", fua = "Здобуваються ювелірами шляхом подрібнення алґарських самоцвітів. Можна купити та продати на Аукціоні." }
    t[213221] = { name = "Подрібнені Самоцвіти", fen = "Acquired by Jewelcrafters by crushing Algari gems. Can be bought and sold on the Auction House.", fua = "Здобуваються ювелірами шляхом подрібнення алґарських самоцвітів. Можна купити та продати на Аукціоні." }
    t[213233] = { name = "Шматки Фунґаріанина", fen = "Some more intact than others, the chunks feel velvety and give slightly under pressure.", fua = "Одні цілісніші за інших, ці шматки оксамитові на дотик і трохи піддаються під натиском." }
    t[213271] = { name = "Наряди на Роботу", fen = "Plans for repairing the Coreway, signed by Councilward Merrix.", fua = "Плани відбудови Серцевинного Шляху, підписані радником Мерріксом." }
    t[213392] = { name = "Ароматична Граната", fen = "A nerubian-made grenade, full of nice, calming smoke. If you're a beetle, that is.", fua = "Граната неруб'янського виробу, повна приємного, заспокійливого диму. Якщо ви, звісно, жук." }
    t[213398] = { name = "Жменя Камінців", fen = "Acquired by Jewelcrafters by prospecting Algari ore. Can be bought and sold on the Auction House.", fua = "Здобувається ювелірами під час старанної обробки алґарської руди. Можна купувати й продавати на Аукціоні." }
    t[213399] = { name = "Блискуче Скло", fen = "Acquired by Jewelcrafters by prospecting Algari ore. Can be bought and sold on the Auction House.", fua = "Здобувається ювелірами під час старанної обробки алґарської руди. Можна купувати й продавати на Аукціоні." }
    t[213402] = { name = "Викривальний Кристал", fen = "A shimmering stone that fits into a Nerubian shadecaster.", fua = "Мерехтливий камінь, що пасує до неруб'янського тінеметача." }
    t[213404] = { name = "Викривальний Сувій", fen = "The page is etched in indecipherable, venomous runes.", fua = "Сторінка викарбувана нерозбірливими, отруйними рунами." }
    t[213405] = { name = "Викривальний Осередок", fen = "Radiates a maddening aura.", fua = "Випромінює божевільну ауру." }
    t[213420] = { name = "Капелюшок Фунґаріанського Гриба", fen = "A mushroom cap taken off the body of Cruelious Agaricus, a particularly nasty fungarian in Pillar-nest Vosh.", fua = "Капелюшок гриба, знятий із тіла Жорстокія Агарікуса, особливо мерзенного фунґаріанина в Стовпогнізді Вош." }
    t[213423] = "Призабутий Талісман Зброї"
    t[213424] = { name = "Барило Медового Трунку «Жаровар»", fen = "The scalding ironwood barrel is almost too hot to hold.", fua = "Розпечене барило із залізодерева майже неможливо втримати в руках." }
    t[213425] = { name = "Пошматований Повід", fen = "It appears the mount didn't enjoy being ridden.", fua = "Схоже, засобу пересування не сподобалося, що на ньому їздять." }
