    t[215236] = { name = "Лютий Кровокамінь", fen = "Acquired rarely through PvP activities, such as battlegrounds or arenas. Can be purchased with Honor. Used to craft and augment Khaz Algar PvP gear in various ways. Can be bought and sold on the Auction House.", fua = "Рідко здобувається через заняття PvP, як-от поля бою чи арени. Можна придбати за честь. Використовується для виготовлення та різноманітного вдосконалення PvP-спорядження Каз Алґару. Можна купувати й продавати на аукціоні." }
    t[215446] = { name = "Понівечений Шолом", fen = "Has clearly seen a lot of action. It has been lovingly repaired multiple times.", fua = "Явно побував у багатьох сутичках. Його не раз дбайливо лагодили." }
    t[215447] = "Сутіньостебло"
    t[215448] = "Рагу з Темностеблу"
    t[215457] = { name = "Виділення Лоялістів", fen = "Found in the pheromone glands of only the most trusted Sureki Acolytes.", fua = "Знаходять у феромонних залозах лише найдовіреніших послушників Сурекі." }
    t[215464] = { name = "Уламок Самоцвіта Пам'яті", fen = "Dull and filled with spiderweb cracks, the gem piece is so fractured it might crumble in your grip. The original gem must have suffered immense physical damage. There is no salvaging this.", fua = "Тьмяний і вкритий павутиною тріщин, цей шматок самоцвіта настільки розколотий, що може розсипатися у вас у руці. Початковий самоцвіт, певно, зазнав величезних фізичних ушкоджень. Це вже не врятувати." }
    t[215466] = { name = "Освячені Припаси", fen = "These supplies are able to dispel the barriers of darkness around the area.", fua = "Ці припаси здатні розвіювати бар'єри темряви довкола." }
    t[215467] = "Кайло Землекраша"
    t[216420] = { name = "Символ Світла", fen = "This symbol is able to produce balls of light that can temporarily disperse shadows.", fua = "Цей символ здатен творити кулі світла, що можуть на мить розганяти тіні." }
    t[216433] = { name = "Викрадена Реліквія", fen = "Light seeps out of this object. You can feel it trying to disperse any shadow around you.", fua = "Світло сочиться з цього предмета. Ви відчуваєте, як воно намагається розвіяти будь-яку тінь довкола вас." }
    t[216524] = { name = "Роз'їдений Сіллю Меч", fen = "This blade has clearly suffered from being immersed in salt water.", fua = "Це лезо явно постраждало від перебування в солоній воді." }
    t[216525] = { name = "Пом'яті Чоботи", fen = "You pulled these boots out of a pile of offal, they smell as you would expect.", fua = "Ви витягли ці чоботи з купи покидьків, і пахнуть вони саме так, як можна очікувати." }
    t[216526] = { name = "Осяйний Щит", fen = "Well loved. It has held up surprisingly well to the salt water.", fua = "Дуже улюблений. Він напрочуд добре витримав солону воду." }
    t[216528] = { name = "Ключ від Скрині Припасів Зблідлого Узбережжя", fen = "The lost key to a supply chest at the Faded Shore.", fua = "Загублений ключ від скрині припасів на Зблідлому Узбережжі." }
    t[216603] = { name = "Чоботи Світла", fen = "These boots hum with holy power while also feeling as light as a feather.", fua = "Ці чоботи гудуть святою силою, водночас здаючись легкими, мов пір'їнка." }
    t[216604] = { name = "\"Дуже Любий\" Плюшевий Ведмедик", fen = "Despite being told this was much loved, it looks barely touched.", fua = "Хоч і кажуть, що його дуже любили, виглядає він майже неторканим." }
    t[216605] = { name = "[UNUSED] Vial of Aggression Pheromone", fen = "A highly-volatile fluid stored in a conveniently throwable bottle.", fua = "Вкрай летка рідина в зручній метальній пляшці." }
    t[216657] = "Тестовий Предмет C"
    t[216658] = { name = "Тіньотворець Сурекі", fen = "Nerubians use these emitters to project orders and messages from their high-ranking leaders.", fua = "Неруби використовують ці випромінювачі, щоб передавати накази й послання своїх високопоставлених очільників." }
    t[216659] = { name = "Тіньотворець Сурекі", fen = "Nerubians use these shadecasters to project orders and messages from their high-ranking leaders.", fua = "Нерубіани використовують ці тінепроектори, щоб передавати накази й послання своїх високопосадовців." }
    t[216660] = { name = "Тіньотворець Сурекі", fen = "Nerubians use these shadecasters to project orders and messages from their high-ranking leaders.", fua = "Нерубіани використовують ці тінепроектори, щоб передавати накази й послання своїх високопосадовців." }
    t[216664] = { name = "Принада для Ниткарів", fen = "A grenade-like object for attracting Rak-Ush threadlings.", fua = "Схожий на гранату предмет для приваблювання ниткарів Рак-Уш." }
    t[216669] = { name = "Розтрощені Рештки", fen = "Part of a once powerful Keyflame.", fua = "Частина колись могутнього Ключового Полум'я." }
    t[216682] = { name = "Запрошення Візира", fen = "An invitation to meet with The Vizier's representative. Suspiciously personal.", fua = "Запрошення на зустріч із представником Візира. Підозріло особисте." }
    t[216683] = "Рушниця Земнокровних"
    t[216684] = "Меч Земнокровних"
    t[216685] = "Щит Земнокровних"
    t[216686] = "Сокира Земнокровних"
    t[216688] = { name = "Ключ від Високих Улоговин", fen = "Ag'thax in the High Hollows will be very happy to get into his new burrow.", fua = "Аг'такс у Високих Улоговинах буде дуже радий потрапити до своєї нової нори." }
    t[216689] = { name = "Голова Альберта", fen = "All that remains of Albert is his eyeless head.", fua = "Усе, що лишилося від Альберта, — його безока голова." }
    t[216693] = { name = "Краб Тіньового Припливу", fen = "Live and snapping, good thing you have a cage!", fua = "Живий і клацає клешнями, добре, що у вас є клітка!" }
    t[216697] = { name = "Перстень-Печатка Радника", fen = "The hefty ring's square stone is worn smooth from time, and its band is etched with foreign letters.", fua = "Квадратний камінь цього важкого персня згладився з часом, а на обідку вигравіювані чужоземні літери." }
    t[216708] = { name = "Свята Свічка", fen = "To honor the fallen and guide the lost.", fua = "Щоб ушанувати полеглих і скерувати заблуканих." }
    t[216772] = { name = "Шепітлива Вибухівка", fen = "Whispers begin echoing in your mind as you pick up these explosives.", fua = "Щойно ви берете цю вибухівку, у вашому розумі починає лунати шепіт." }
    t[216858] = { name = "Дубинка Фрейдрина", fen = "An otherworldly life energy resonates through the wood.", fua = "Крізь дерево пульсує неземна життєва енергія." }
    t[216882] = { name = "Запис у Журналі 467-21-5", fen = "Observation: Mycelium expansion noted at an alarming rate, infiltrating neighboring vegetation. Fungarians display a heightened response to environmental stimuli, showcasing a potential shift in their ecological behavior.", fua = "Спостереження: розростання міцелію з тривожною швидкістю, він проникає в сусідню рослинність. Фунґаріани демонструють посилену реакцію на подразники довкілля, що свідчить про можливу зміну їхньої екологічної поведінки." }
    t[216888] = { name = "Запис у Журналі 652-12-3", fen = "Notation: Fungarians demonstrate aggressive mycorrhizal interactions, outcompeting nearby fungal species. The accelerated growth raises concerns about potential ecological imbalances in the affected area.", fua = "Примітка: фунґаріани виявляють агресивні мікоризні взаємодії, витісняючи сусідні види грибів. Прискорене зростання викликає занепокоєння через можливі екологічні порушення в ураженій зоні." }
    t[216889] = { name = "Запис у Журналі 893-03-9", fen = "Observation: Fungarians now spreading beyond the initial study site. Aggressive mycelial intrusion observed in unexpected habitats. Urgent investigation needed to assess the broader ecological impact of this newfound behavior (...)", fua = "Спостереження: фунґаріани тепер поширюються за межі початкової ділянки дослідження. У несподіваних середовищах помічено агресивне проникнення міцелію. Потрібне термінове розслідування, щоб оцінити ширший екологічний вплив цієї нової поведінки (...)" }
    t[216905] = "Сокира Бранна Бронзбірда"
    t[216906] = "Стара Вірна"
    t[216915] = { name = "Екскаватор", fen = "Faded, dirt encrusted letters are scratched into the blade: \"Pick up, throw way.\"", fua = "На лезі видряпані вицвілі, забиті брудом літери: \"Підняти, відкинути\"." }
    t[216982] = { name = "Список Шпигунів", fen = "This list has the names of the Weaver's spies stationed throughout the nerubian empire.", fua = "У цьому списку записані імена шпигунів Ткалі, розставлених по всій нерубській імперії." }
    t[217040] = { name = "Вушна Сірка Кобольда", fen = "Gross.", fua = "Гидота." }
    t[217041] = { name = "Ріг Проголошення", fen = "Urtago gave you this horn. Using it would briefly share your knowledge with others around you.", fua = "Цей ріг дав вам Уртаґо. Використавши його, ви на мить поділитеся своїми знаннями з тими, хто поруч." }
    t[217042] = { name = "Випромінювач Феромонів Зев'калла", fen = "This large emitter contains Zev'kall's alchemized pheromones, since he cannot create them himself.", fua = "Цей великий випромінювач містить алхімічно створені феромони Зев'калла, бо сам він виробляти їх не може." }
    t[217105] = { name = "Очищення Трав Каз Алґару", fen = "Refine herbs gathered from Khaz Algar to higher qualities.", fua = "Очищає трави, зібрані в Каз Алґарі, до вищої якості." }
    t[217107] = { name = "Нотатки Модіни", fen = "The slate tablet is carefully etched with earthen writing.", fua = "Сланцева табличка ретельно вкрита різьбленим письмом земних." }
    t[217108] = { name = "Торба Руди Модіни", fen = "Filled with red ore that looks exclusive to Gemvein Tunnels.", fua = "Наповнена червоною рудою, що, схоже, трапляється лише в Самоцвітножильних Тунелях." }
