    t[217142] = { name = "Кінцівка земельника", fen = "Most likely an earthen arm, identifiable by a braided pattern and a fractured gem on the back of the wrist. The stone is enormously heavy for its size. Deep, branching fissures run from both ends, indicating a violent parting from the body.", fua = "Найімовірніше, рука земельника, упізнавана за плетеним візерунком і тріснутим самоцвітом на тильному боці зап'ястка. Камінь надзвичайно важкий як на свій розмір. З обох кінців тягнуться глибокі розгалужені тріщини, що вказують на жорстоке відокремлення від тіла." }
