    t[217162] = { name = "Намисто з Коболдячих Зубів", fen = "Small, sharp, and probably stolen.", fua = "Маленькі, гострі й, напевно, крадені." }
    t[217163] = { name = "Добряче Зношена Лялька", fen = "\"Mr. Snugglewick\" is shakily written on the back of the doll.", fua = "На звороті ляльки тремтливо написано \"Пан Затишничок\"." }
    t[217164] = { name = "Королівська Колупачка для Нігтів", fen = "A captured earthen blade, rusty and dented beyond usefulness. Crusted in things better left unpondered.", fua = "Захоплений клинок земельників, іржавий і вищерблений до повної непридатності. Вкритий кіркою з речей, про які краще не думати." }
    t[217165] = { name = "Журнал Втрат Зев'калла", fen = "A detailed description of the losses of nerubian troops at the Siegehold.", fua = "Докладний опис утрат нерубських військ біля Облогової Твердині." }
    t[217167] = { name = "Запеклий Кубок", fen = "An old boot stained with wine and other, darker, things.", fua = "Старий чобіт, заплямований вином та іншими, темнішими, речами." }
    t[217168] = { name = "Шоколадні Монети", fen = "Some of the coins have bites taken out. None were unwrapped first.", fua = "З деяких монет відкушено шматки. Жодну спершу не розгорнули." }
    t[217169] = { name = "Плащ із Борід", fen = "Crudely woven from the shorn, wiry beards of fallen earthen.", fua = "Грубо зітканий зі зголених, цупких борід полеглих земельників." }
    t[217170] = { name = "Запасні Свічки", fen = "Never have enough! - Skitter", fua = "Ніколи не буває забагато! - Дріботуха" }
    t[217171] = { name = "ЩОДЕННИК СВІЧКОВОГО КОРОЛЯ", fen = "Thick book. Heavy book. Many words.", fua = "Товста книга. Важка книга. Багато слів." }
    t[217175] = { name = "Голова Гостролуска", fen = "Dripping with blood and water, you can smell the fetid stench coming from this even in your bag.", fua = "Скрапуючи кров'ю і водою, вона так смердить, що ви чуєте сморід навіть із торби." }
    t[217269] = { name = "Просочений Магією Орган", fen = "A strange dust that crackles with arcane power permeates the crab's organ.", fua = "Дивний пил, що тріщить магічною силою, пронизує орган краба." }
    t[217309] = "Бойовий Ріг Араті"
    t[217310] = { name = "Перший Сувій Наглядача", fen = "The first scroll left behind by the foreman of Taelloch", fua = "Перший сувій, залишений наглядачем Таеллоху." }
    t[217311] = { name = "Другий Сувій Наглядача", fen = "The second scroll left behind by the foreman of Taelloch", fua = "Другий сувій, залишений наглядачем Таеллоху." }
    t[217312] = { name = "Третій Сувій Наглядача", fen = "The third scroll left behind by the foreman of Taelloch", fua = "Третій сувій, залишений наглядачем Таеллоху." }
    t[217342] = { name = "Безстрашний Трунок", fen = "A favorite of Captain Lancekat and the Dauntless crew.", fua = "Улюбленець капітана Лансекет і команди «Безстрашного»." }
    t[217343] = { name = "Живий Згуслий Намул", fen = "Primordial energy courses through the elemental silt.", fua = "Первинна енергія струмує крізь стихійний намул." }
    t[217344] = "Пускач Сигнальних Ракет Вартового"
    t[217352] = { name = "Задихана Риба", fen = "Its dehydrated lips faintly move, yearning to whisper.", fua = "Її висохлі губи ледь ворушаться, прагнучи шепотіти." }
    t[217386] = { name = "Викинутий Самоцвіт Пам'яті", fen = "The nerubians found nothing valuable in this gem.", fua = "Неруби не знайшли в цьому самоцвіті нічого цінного." }
    t[217396] = "Яйце з Пагорба Гіллгелм"
    t[217400] = "Принада на Кобіса"
