    t[217403] = "Прадавній Чар Зброї"
    t[217404] = "Потертий Часом Чар Броні"
    t[217405] = "Потертий Часом Чар Зброї"
    t[217414] = { name = "Пропускна Руна Шинку", fen = "Traced in the likeness of a cog, the passrune bears many sharp edges and details. Only a skilled Machine Speaker could trace this from memory.", fua = "Накреслена за подобою шестерні, ця пропускна руна має багато гострих країв і деталей. Лише вправний Мовець із Машинами зміг би накреслити її з пам'яті." }
    t[217498] = { name = "Конфіскований Вантаж", fen = "Nothing unusual.", fua = "Нічого незвичайного." }
    t[217499] = { name = "Набір Зубил", fen = "Different shapes and sizes, specialized for a variety of stone types.", fua = "Різних форм і розмірів, призначені для різноманітних типів каменю." }
    t[217500] = { name = "Високоякісне Вугілля", fen = "Sturdy briquettes able to burn for several hours at a time.", fua = "Міцні брикети, здатні горіти по кілька годин поспіль." }
    t[217501] = { name = "Фартух із Кротячої Шкіри", fen = "Prevents scorching and splatter from molten metal.", fua = "Захищає від опіків і бризок розплавленого металу." }
    t[217502] = { name = "Просочена Підглина", fen = "Infused with holy oil from Hallowfall, this mud can burn for weeks on end.", fua = "Просочена святою олією зі Святолуння, ця глина може горіти тижнями поспіль." }
    t[217503] = { name = "Нерубські Шовкові Мотузки", fen = "Woven from nerubian webs, these flexible ropes are unbreakable.", fua = "Сплетені з нерубського павутиння, ці гнучкі мотузки незламні." }
    t[217504] = { name = "Стос Розписок", fen = "Each one is signed by the same person: 'Steelvein.'", fua = "Кожну підписала одна й та сама особа: \"Сталевен\"." }
    t[217505] = { name = "Торба Сяючих Скалок", fen = "These small shards break easily, producing an invigorating spark of electricity.", fua = "Ці маленькі скалки легко розбиваються, видаючи бадьорливу електричну іскру." }
    t[217506] = "Test Item [DNT]"
    t[217610] = { name = "Самоцвіт Пам'яті Земельників", fen = "This square-cut gem is heavy for its size and emits a faint glow. Engineered for earthen programming and memories, this gem-like cache is removable and can be uploaded to the earthen Archive.", fua = "Цей квадратно огранений самоцвіт важкий як на свій розмір і випромінює слабке сяйво. Створений для програмування та зберігання спогадів земельників, цей схожий на самоцвіт сховок є знімним і може бути завантажений до Архіву земельників." }
    t[217614] = { name = "Аратійський Пайок", fen = "A simple stew made from hearty ingredients. Filling, comforting, and lacking salt.", fua = "Проста юшка з ситних складників. Поживна, заспокійлива і недосолена." }
    t[217694] = { name = "Ідентифікаційна Табличка Земельників 1103a572", fen = "Unit: 1103a572 - Function: Steelshaper - Activation: 062.71002 - Name: Gerundt", fua = "Одиниця: 1103a572 - Функція: Формувальник сталі - Активація: 062.71002 - Ім'я: Герундт" }
    t[217695] = { name = "Ідентифікаційна Табличка Земельників 3481a662", fen = "Unit: 3481a662 - Function: Earthcarver - Activation: 128.10889 - Name: Fridya", fua = "Одиниця: 3481a662 - Функція: Різьбярка землі - Активація: 128.10889 - Ім'я: Фрідья" }
    t[217696] = { name = "Ідентифікаційна Табличка Земельників 2672b138", fen = "Unit: 2672b138 - Function: Forgecaller - Activation: 037.51972 - Name: Grinte", fua = "Одиниця: 2672b138 - Функція: Закликач кузні - Активація: 037.51972 - Ім'я: Грінте" }
    t[217699] = { name = "Ідентифікаційна Табличка Земельників 0985e438", fen = "Unit: 0985e438 - Function: Control Node - Activation: 237.18623 - Name: Trandthe", fua = "Одиниця: 0985e438 - Функція: Вузол керування - Активація: 237.18623 - Ім'я: Трандте" }
    t[217707] = { name = "Недосконалий Камінь Порожнечі", fen = "Sometimes gathered by players with the Mining skill. Can be bought and sold on the Auction House.", fua = "Іноді видобувається гравцями з умінням гірничої справи. Можна купити й продати на Аукціоні." }
    t[217709] = { name = "Безсонячна Скалка", fen = "Amid coral and driftwood, flecks of dark crystal reflect no light.", fua = "Серед коралів і плавнику цяточки темного кристалу не відбивають світла." }
    t[217715] = { name = "Ключовий Сувій", fen = "This strange scroll is able to control one of the doors within the Underkeep.", fua = "Цей дивний сувій здатен керувати однією з дверей у Глибиннику." }
    t[217816] = { name = "Зволожена Риба", fen = "A lack of water seems to bother it no longer.", fua = "Здається, брак води її більше не турбує." }
    t[217818] = { name = "Очищення Алґарських Шкур", fen = "Refine rare hides and carapace gathered from the creatures of Khaz Algar to higher qualities.", fua = "Покращує якість рідкісних шкур і панцирів, зібраних зі створінь Каз Алґару." }
    t[217822] = { name = "Очищення Алґарської Шкіри", fen = "Refine leather gathered from the creatures of Khaz Algar to higher qualities.", fua = "Покращує якість шкіри, зібраної зі створінь Каз Алґару." }
    t[217840] = { name = "Очищення Алґарського Хітину", fen = "Refine chitin gathered from the creatures of Khaz Algar to higher qualities.", fua = "Покращує якість хітину, зібраного зі створінь Каз Алґару." }
    t[217853] = "<Вставити Особливе Чаклунське Спорядження>"
    t[217894] = "Нерубський Виділювач Феромонів"
    t[217895] = { name = "Нестійкий Феромон", fen = "A strange chemical swirls within this bottle. It probably doesn't have any long-lasting side effects... right?", fua = "У цій пляшці вирує дивна хімічна речовина. Напевно, вона не має жодних тривалих побічних ефектів... чи не так?" }
    t[217897] = { name = "Нестійкий Феромон", fen = "This container shakes from the odd substance within it.", fua = "Цей контейнер тремтить від дивної речовини всередині." }
    t[217965] = { name = "Ремонтний Набір", fen = "The sound of tools rustling around in here is enough to make you want to fix something.", fua = "Самого звуку інструментів, що тут торохкотять, досить, аби захотілося щось полагодити." }
    t[217986] = { name = "\"Смачні\" Частини Яєць", fen = "Kobold chefs around the Undermine agree! No meal is complete without these eggs.", fua = "Кухарі-кобольди по всьому Підкопу одностайні! Жодна страва не обходиться без цих яєць." }
    t[217996] = { name = "Данина Сурекі", fen = "Heavy with currency and marked for delivery to the Royal Vaults.", fua = "Важка від монет і призначена для доставки в Королівські Сховища." }
    t[217999] = { name = "Смачна Мідія", fen = "This mussel could easily be used for any number of delicious dishes.", fua = "Цю мідію легко можна використати для безлічі смачних страв." }
    t[218000] = { name = "Мішок Прянощів", fen = "These spices could be used to make a fantastic meal, though the dust around the bag indicates it hasn't seen much use.", fua = "З цих прянощів можна було б приготувати неперевершену страву, та пил навколо мішка свідчить, що ними майже не користувалися." }
    t[218002] = { name = "Безцінний Гарбуз", fen = "This pumpkin has a delightful smell to it.", fua = "Цей гарбуз має чудовий аромат." }
    t[218042] = { name = "Контролер Ремі", fen = "Something Seraphine wired together for you to use.", fua = "Щось, що Серафіна зібрала докупи, щоб ви цим скористалися." }
    t[218085] = { name = "Флакон Рідкого Опалу", fen = "Contained within a rune-bound bottle, this swirling cocktail is a mixture of various rare liquid minerals found across the caverns of Khaz Algar.", fua = "Замкнений у пов'язаній рунами пляшці, цей вируючий коктейль є сумішшю різних рідкісних рідких мінералів, що трапляються в печерах Каз Алґара." }
