    t[218100] = { name = "Креслення: <Optional Reagnt A>", fen = "Teaches you how to craft <Optional Reagnt A>.", fua = "Навчає вас виготовляти <Optional Reagnt A>." }
    t[218101] = { name = "Креслення: <PVP Alloy>", fen = "Teaches you how to craft <PVP Alloy>.", fua = "Навчає вас виготовляти <PVP Alloy>." }
    t[218102] = { name = "Закривавлені Креслення: <PVP Alloy>", fen = "Teaches you how to craft <PVP Alloy>. This scroll is soaked in far too much blood to try to sell or trade.", fua = "Навчає вас виготовляти <PVP Alloy>. Цей сувій надто просякнутий кров'ю, щоб його продавати чи обмінювати." }
