    t[218104] = { name = "[UNUSED] Vial of Aggression Pheromone", fen = "Only two vials of this highly-volatile fluid remain, but that should be enough.", fua = "Лишилося тільки два флакони цієї вкрай летючої рідини, але цього має вистачити." }
    t[218106] = "Жаб'яча Пастка Тихокаменю"
    t[218107] = { name = "Глек зі Світлячками", fen = "The small luminescent bugs inside provide a fanciful colorful light.", fua = "Маленькі світні жучки всередині дарують химерне барвисте світло." }
    t[218113] = { name = "Отрута Солодкожала", fen = "Spicy and perhaps sweet, but not to eat.", fua = "Пряна й, можливо, солодка, та не для їжі." }
    t[218121] = { name = "Світло Свічки", fen = "You, in fact, did take candle.", fua = "Ви таки взяли свічку." }
    t[218122] = { name = "Викрадена Реліквія", fen = "The light within this relic still glows despite the kobyss attempting to corrupt it.", fua = "Світло в цій реліквії досі сяє, попри спроби кобіссів його споганити." }
    t[218123] = { name = "Сяйлива Скалка", fen = "You were able to brush off any of the grime used to dim the radiance of this shard.", fua = "Вам удалося стерти весь бруд, яким приглушили сяйво цієї скалки." }
    t[218124] = { name = "Видобувач Стихій", fen = "A gadget that detects and extracts unwavery powers from Elementals.", fua = "Пристрій, що виявляє та видобуває непохитні сили з елементалів." }
    t[218125] = "Реактивний Оплетений Гербовий Щит"
    t[218126] = "Шприц Опоганювача"
    t[218127] = { name = "Вічноквітучий Гриб", fen = "Fast growing the seem to sprout on everything.", fua = "Швидкорослий, він, здається, проростає на всьому." }
    t[218129] = "Порцеляновий Ідол-Наконечник"
    t[218131] = { name = "Бездоганна Шапка Батогогриба", fen = "This lashroom cap is the perfect balance of squishy and absorbent, while also being sturdy enough to caress the rocky plains of a moss-covered earthen.", fua = "Ця шапка хлестогриба має бездоганний баланс м'якості й вбирності, до того ж досить міцна, щоб пестити кам'янисті рівнини вкритого мохом землянина." }
    t[218187] = { name = "Їдка Квітка", fen = "The flowers of this orange plant can be used to create a caustic solvent, when mixed with water.", fua = "Квіти цієї помаранчевої рослини можна використати для створення їдкого розчинника, змішавши їх із водою." }
    t[218188] = { name = "Налаштувальний Кристал", fen = "The crystal emits a lovely, gentle hum.", fua = "Кристал видає приємний м'який гул." }
    t[218241] = "11.0 Leveling Quest Template - Belt"
    t[218307] = "Гніт Дикополум'я"
    t[218336] = { name = "Хітин Рою Кагеті", fen = "A rare, species-specific material gathered from the lesser minions of Nerubians by players with the Skinning skill. Can be bought and sold on the Auction House.", fua = "Рідкісний видовий матеріал, який гравці з умінням шкуродерства збирають із нижчих поплічників нерубів. Можна купувати й продавати на Аукціоні." }
    t[218337] = { name = "Загострені Кісткові Скалки", fen = "A rare, species-specific material gathered from creatures with horns or tusks by players with the Skinning skill. Can be bought and sold on the Auction House.", fua = "Рідкісний видовий матеріал, який гравці з умінням шкуродерства збирають із істот із рогами чи бивнями. Можна купувати й продавати на Аукціоні." }
    t[218338] = { name = "Буря в Пляшці", fen = "A rare, species-specific material gathered from storm creatures by players with the Skinning skill. Can be bought and sold on the Auction House.", fua = "Рідкісний видовий матеріал, який гравці з умінням шкуродерства збирають із бурехідних істот. Можна купувати й продавати на Аукціоні." }
    t[218339] = { name = "Палаючі Щетинки Попелястої Бджоли", fen = "A rare, species-specific material gathered from cinderbees by players with the Skinning skill. Can be bought and sold on the Auction House.", fua = "Рідкісний видовий матеріал, який гравці з умінням шкуродерства збирають із попелястих бджіл. Можна купувати й продавати на Аукціоні." }
