    t[219815] = { name = "Маленьке Руків'я", fen = "A hilt made for a small hand. On second glance it becomes obvious that it was part of a toy.", fua = "Руків'я, зроблене для маленької руки. Придивившись, стає очевидно, що воно було частиною іграшки." }
