    t[221550] = { name = "Капелюшок Лісокореня", fen = "This mushroom grows in the Boskroot Basin. While the local fungarians sees it as a delicacy, it is otherwise inedible to non-fungarians, smells rotten, and is covered by a sticky film.", fua = "Цей гриб росте в Лісокореневій Улоговині. Хоча місцеві грибарі вважають його делікатесом, для інших він неїстівний, тхне гнилизною й укритий липкою плівкою." }
