    t[221751] = { name = "DO NOT USE Призматичний Кодекс", fen = "A handheld device with a single slot for an earthen memory gem. Use it to play a single memory from the gem.", fua = "Ручний пристрій з єдиним гніздом для самоцвіта пам'яті земельників. Використайте його, щоб відтворити окремий спогад із самоцвіта." }
    t[221753] = { name = "Тліюча Попеляста Бджола", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[221754] = { name = "Злиток Дзвінких Глибин", fen = "A masterfully forged slab of Algari metal; stalwart yet malleable. Can be bought and sold on the Auction House.", fua = "Майстерно викувана пластина алґарського металу; міцна, але податлива. Можна купити й продати на Аукціоні." }
    t[221755] = { name = "Зілля Світлотіні", fen = "A bottle full of bright orange liquid with insect ligaments suspended in the solution.", fua = "Пляшка, повна яскраво-помаранчевої рідини, у якій плавають частини комах." }
    t[221756] = { name = "Флакон Кахетійських Олій", fen = "A fusion of alchemical weave and artisanal prowess. Kaheti dark alchemy. Can be bought and sold on the Auction House.", fua = "Поєднання алхімічного плетива та ремісничої майстерності. Темна алхімія кахеті. Можна купити й продати на Аукціоні." }
    t[221757] = { name = "Шкіра Морочних Глибин", fen = "An immensely sturdy hide from an animal you are unable to identify. Can be bought and sold on the Auction House.", fua = "Надзвичайно міцна шкіра тварини, яку ви не можете розпізнати. Можна купити й продати на Аукціоні." }
    t[221758] = { name = "Осквернене Кресало", fen = "A standard-issue tinderbox of the Arathi. It contains flint, steel, and a tincture of imbued oil. Can be bought and sold on the Auction House.", fua = "Стандартне кресало араті. Містить кремінь, кресало та настоянку наснаженої олії. Можна купити й продати на Аукціоні." }
