    t[222922] = { name = "Важка скриня", fen = "May contain equipment, recipes, currencies, collectibles, and curios.", fua = "Може містити спорядження, рецепти, валюту, колекційні речі та дивовижі." }
    t[222923] = { name = "Експедиційна Здобич", fen = "May contain equipment, exotic reagents, collectibles, and secret recipes.", fua = "Може містити спорядження, екзотичні реагенти, колекційні предмети та таємні рецепти." }
    t[222924] = { name = "Нутрощі Печінкошукача", fen = "Though full of others' livers chewed up, Liverseeker's liver is rather petite.", fua = "Хоч і повна пережованих чужих печінок, власна печінка Печінкошукача доволі маленька." }
    t[222925] = { name = "Міцне Волокно Плюща", fen = "This ivy is practically a rope even before it has been worked.", fua = "Цей плющ — практично готова мотузка ще до того, як його обробили." }
    t[222926] = { name = "Шлунок Ногогриза", fen = "Chunks of leg here. Also chunks of arm, eye, face... Chunks of everything, really.", fua = "Тут шматки ніг. А ще шматки рук, очей, облич... Власне, шматки всього." }
    t[222927] = { name = "Потерта Скринька з Монетами", fen = "Contains a variety of currencies including gold, Undercoin, Valorstones, Resonance Crystals, and Weathered Crests.", fua = "Містить різноманітні валюти, зокрема золото, підмонети, камені звитяги, кристали резонансу та потерті герби." }
    t[222928] = "Скринька для Монет"
    t[222929] = { name = "Різьблена Скринька з Монетами", fen = "Contains a variety of currencies including gold, Undercoin, Valorstones, Resonance Crystals, and Carved Crests.", fua = "Містить різноманітні валюти, зокрема золото, підмонети, камені звитяги, кристали резонансу та різьблені герби." }
    t[222944] = { name = "Набряклий Мозок Ненажерливості", fen = "Not appetizing. And you aren't certain why your first instinct was to assess its appeal as food.", fua = "Геть не апетитно. І ви не зовсім розумієте, чому вашим першим поривом було оцінити, чи годиться це на їжу." }
    t[222953] = { name = "Скупані у Світлі Пагони Лотоса", fen = "Glows slightly. Tastes faintly of peacebloom, but with a citrusy twist.", fua = "Злегка світяться. На смак ледь відчутно нагадують миротворку, але з цитрусовою ноткою." }
    t[222954] = { name = "Рунічна Скринька з Монетами", fen = "Contains a variety of currencies including gold, Undercoin, Valorstones, Resonance Crystals, and Runed Crests.", fua = "Містить різноманітні валюти, зокрема золото, підмонети, камені звитяги, кристали резонансу та рунічні герби." }
