    t[223979] = { name = "Шепітливий Звивистий Черв'як", fen = "Emits a faint whisper by rubbing the scales of its body against itself. Great for catching fish across Khaz Algar.", fua = "Видає тихий шепіт, тручи лусочки свого тіла одну об одну. Чудовий для лову риби по всьому Каз Алґару." }
    t[224007] = { name = "Застосування Решток Оболонок (Як Їх Розбирати)", fen = "A somewhat detailed guide to using what's left after an arachnoid consumes its prey. Mildly useful to skinners, disgusting for all.", fua = "Доволі докладний посібник із використання того, що лишається після того, як павукоподібне поглинає свою здобич. Помірно корисний білувальникам, гидкий для всіх." }
    t[224008] = { name = "Загублений Інструмент", fen = "Someone could trip over this.", fua = "Хтось міг би через нього перечепитися." }
