    t[224023] = { name = "Техніки Бальзамування Травами", fen = "A small book describing how to use rare herbs from Khaz Algar and Northrend to perfectly preserve a corpse to retain its flavor. Could be useful for herbalists.", fua = "Маленька книга, що описує, як використати рідкісні трави з Каз Алґару й Нортренду, щоб ідеально зберегти труп задля збереження його смаку. Може бути корисна травникам." }
    t[224024] = { name = "Теорії Тілесної Трансмутації, Розділ 8", fen = "Abstract theory about the alchemical side effects of transforming one's body permanently. Could be useful to alchemists.", fua = "Абстрактна теорія про алхімічні побічні ефекти від остаточного перетворення власного тіла. Може бути корисна алхімікам." }
    t[224025] = { name = "Тріскотлива Скалка", fen = "Even when idle, the wrath of a storm hums and snaps beneath its surface.", fua = "Навіть у спокої гнів бурі гуде й клацає під її поверхнею." }
