    t[224038] = { name = "Ковальство Після Сароніту", fen = "A small, worn pamphlet instructing nerubian smiths how to adapt to working with more mundane materials instead of the saronite they once worked. Might be useful for blacksmiths.", fua = "Маленький, потертий памфлет, що повчає нерубських ковалів, як пристосуватися до роботи зі звичайнішими матеріалами замість сароніту, з яким вони працювали колись. Може бути корисний ковалям." }
