    t[224053] = { name = "Вісім Поглядів на Захист від Ворожих Рун", fen = "Subtitled \"Lessons from the Fall of Ahn-Kahet,\" this tome examines potential ways to disrupt and deflect the runic power of the Lich King and his servants. Might be useful to scribes.", fua = "З підзаголовком \"Уроки з Падіння Ан-Кахету\", цей фоліант досліджує можливі способи порушити й відхилити рунічну силу Короля-Ліча та його слуг. Може бути корисний накреслювачам." }
    t[224054] = { name = "Висхідні Кристали Мешканців Поверхні", fen = "A freshly printed pamphlet theorizing about use of Resonance Crystals in nerubian gemwork. Useful for jewelcrafters.", fua = "Свіжовидрукуваний памфлет, що теоретизує про застосування Кристалів Резонансу в нерубській роботі із самоцвітами. Корисний для ювелірів." }
    t[224055] = { name = "Кам'янистий Початок", fen = "A tome of nerubian mining techniques aimed at a journeyman learning the craft. Useful for miners.", fua = "Фоліант нерубських гірничих технік, призначений для підмайстра, що опановує ремесло. Корисний для гірників." }
    t[224056] = { name = "Застосування Решток Оболонок (Після Того, Як Ти Їх Розбереш)", fen = "A grisly tome discussing productive mutilation of corpses to create useful leather works. It includes ways to use husks of both Alliance and Horde races. Useful for non-squeamish leatherworkers.", fua = "Моторошний фоліант, що оповідає про продуктивне розчленування трупів задля створення корисних шкіряних виробів. Він містить способи використання оболонок рас як Альянсу, так і Орди. Корисний для нечутливих чинбарів." }
