    t[224185] = { name = "Гілка для Скеровування Крабів", fen = "The key to the cave tree mystery.", fua = "Ключ до таємниці печерного дерева." }
    t[224186] = { name = "Гімни Полум'я", fen = "The contents of this book definitely do not match the title.", fua = "Вміст цієї книги аж ніяк не відповідає назві." }
    t[224187] = { name = "Пом'ятий Наконечник Списа", fen = "This battleworn spearhead is attached to a chain. It appears to be a trophy of some sort.", fua = "Цей побитий у боях наконечник списа прикріплено до ланцюга. Схоже, це якийсь трофей." }
    t[224188] = { name = "Філігранний Священник", fen = "While the design of this Light's Gambit piece suggests it was intended to be decorative, it holds quite a bit of wear and tear.", fua = "Хоч оздоблення цієї фігури для Гамбіту Світла вказує на те, що вона мала бути декоративною, на ній чимало слідів зношення." }
    t[224189] = { name = "Кістяна Кресальниця", fen = "An ornate tinderbox made from an unknown ivory source. There is a noble figure carved into the lid.", fua = "Оздоблена кресальниця, зроблена з кістки невідомого походження. На кришці вирізьблено постать вельможі." }
    t[224232] = { name = "Гнилі Тельбухи Кобіса", fen = "A truth revealed as you stare at this meat: The kobyss must have no sense of smell.", fua = "Дивлячись на це м'ясо, ти усвідомлюєш істину: кобіси, певно, геть позбавлені нюху." }
    t[224238] = { name = "Стерта Монета", fen = "A small copper coin of foreign print.", fua = "Маленька мідна монета чужоземного карбу." }
    t[224239] = { name = "Купа Шкіряних Шнурків", fen = "A collection of aviator hair ties that have amassed into one gnarled mess.", fua = "Зібрання авіаторських стрічок для волосся, що сплелися в один заплутаний клубок." }
    t[224240] = { name = "Нерубіанський Надгробок", fen = "Wars against the Scourge have taught nerubians to cremate their dead, but they still use tombstones to commemorate the fallen.", fua = "Війни проти Погибелі навчили нерубіан спалювати своїх мертвих, та вони досі використовують надгробки, щоб ушановувати загиблих." }
    t[224250] = { name = "Іграшкова Риба", fen = "A large fish made of wood and leather. It has multiple large gouges on its surface.", fua = "Велика риба з дерева й шкіри. На її поверхні чимало глибоких борозен." }
    t[224251] = { name = "Акорд Спогадів", fen = "Drawn from a lifetime of memories.", fua = "Витягнутий з цілого життя спогадів." }
    t[224252] = { name = "Закам'янілий Щоденник", fen = "Wrenching this book open reveals that the central pages are largely intact. They are full of sketches of an unfamiliar landscape.", fua = "Коли вдається силоміць відкрити цю книгу, виявляється, що центральні сторінки здебільшого вціліли. Вони повні замальовок незнайомого краєвиду." }
    t[224254] = { name = "Дерев'яна Фігурка", fen = "A roughly carved statuette. It depicts a lynx running through flames.", fua = "Грубо вирізьблена статуетка. Вона зображає рись, що мчить крізь полум'я." }
    t[224256] = { name = "Торба Сердитих Грибів", fen = "The bag is quite restless.", fua = "Торба досить неспокійна." }
    t[224257] = { name = "Міцний Медальйон", fen = "Where a portrait normally sits instead contains a flower pressed and preserved between glass.", fua = "Там, де зазвичай розташований портрет, натомість лежить квітка, засушена й збережена під склом." }
    t[224258] = "[DNT] Flower"
