    t[224266] = { name = "Кістяна Кресальниця", fen = "An ornate tinderbox made from an unknown ivory source. There is a noble figure carved into the lid.", fua = "Оздоблена кресальниця, зроблена з кістки невідомого походження. На кришці вирізьблено постать вельможі." }
