    t[224272] = { name = "Закам'янілий Щоденник", fen = "Wrenching this book open reveals that the central pages are largely intact. They are full of sketches of an unfamiliar landscape.", fua = "Коли вдається силоміць відкрити цю книгу, виявляється, що центральні сторінки здебільшого вціліли. Вони повні замальовок незнайомого краєвиду." }
