    t[224457] = { name = "Малий Поросятко", fen = "A small piglet out on an adventuresome stroll.", fua = "Маленьке порося на пригодницькій прогулянці." }
    t[224460] = { name = "Загублений Щоденник", fen = "One look at the text reveals a salacious account of scandalous escapades.", fua = "Один погляд на текст відкриває непристойний опис скандальних витівок." }
    t[224462] = { name = "Вухо", fen = "It's definitely a human ear.", fua = "Це безперечно людське вухо." }
    t[224463] = { name = "Медальйон Лілі", fen = "The Inscription reads, Glow brightly, with love from Gerta.", fua = "Напис гласить: \"Сяй яскраво, з любов'ю від Герти.\"" }
    t[224465] = { name = "Незвичайна Картоплина", fen = "It bears a striking resemblance to General Steelstrike... if you squint.", fua = "Вона разюче схожа на генерала Стілстрайк... якщо примружитися." }
    t[224466] = { name = "Курка Вілбер", fen = "Just as surprised as you to find itself in this predicament.", fua = "Здивована потрапити в таку халепу не менше за тебе." }
    t[224467] = "Забута Сокира"
    t[224486] = { name = "Дядькове Око", fen = "Crafted from delicate glass, yet undeniably essential in completing a face.", fua = "Виготовлене з тендітного скла, та безперечно необхідне, щоб довершити обличчя." }
    t[224545] = { name = "Леміш", fen = "Pristine and unused, this is a valuable tool for farming.", fua = "Бездоганний і не вживаний, це цінне знаряддя для землеробства." }
    t[224548] = { name = "Нерубіанський Пристрій", fen = "The markings on it unmistakably bear the signature of Nerubian magic.", fua = "Знаки на ньому безсумнівно несуть відбиток нерубіанської магії." }
    t[224549] = { name = "Свисток Каналізаційної Черепахи", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[224552] = { name = "Смолоскип Печерного Дослідника", fen = "C'mon! We have adventures to go on.", fua = "Ходімо! На нас чекають пригоди." }
    t[224553] = { name = "Налаштування на Беледар", fen = "A fragment corrupted by Beledar's Shadow.", fua = "Уламок, спаплюжений Тінню Беледара." }
    t[224554] = { name = "Скіпетр Світлої Надії", fen = "Truth be told, I love the view up here.", fua = "Як по правді, я обожнюю краєвид звідси, згори." }
    t[224555] = { name = "Самоцвіт Спогадів Арбауха", fen = "The memory gem of Foreman Arbauch. This should be returned to the archives.", fua = "Самоцвіт спогадів майстра Арбауха. Його варто повернути до архіву." }
    t[224556] = { name = "Скриня Славетного Суперника", fen = "An impressive stockpile of various goods. May contain profession reagents, recipe scrolls, PvP consumables, and more!", fua = "Вражаючий запас різноманітних товарів. Може містити реагенти професій, сувої з рецептами, видаткові предмети для PvP і не тільки!" }
    t[224557] = { name = "Доплата за ризик польового медика", fen = "A stockpile of miscellaneous goods that compensates for the underappreciated work out in the battlefield.", fua = "Запас різноманітних товарів, що відшкодовує недооцінену працю на полі бою." }
    t[224572] = { name = "Кристалізована Руна Підсилення", fen = "Can be bought and sold on the auction house.", fua = "Можна купити та продати на аукціоні." }
    t[224573] = { name = "Кристалева Торбина Співпраці", fen = "Filled to the brim with gold and augment runes.", fua = "Наповнена по вінця золотом та рунами вдосконалення." }
    t[224575] = "Підвіска Світлоносця"
    t[224577] = { name = "Сфера Безкінечних Перетворень (Лише PTR)", fen = "Counts as a Philosopher's Stone.", fua = "Зараховується як філософський камінь." }
