    t[224721] = { name = "Запечатана Воском Коробка", fen = "This box jingles with coin as you shake it.", fua = "Коли ви трясете цю коробку, у ній бряжчать монети." }
    t[224722] = { name = "Восковий Згорток з Кристалами Резонансу", fen = "A collection of Resonance Crystals found by kobolds all over Khaz Algar.", fua = "Зібрання Кристалів Резонансу, знайдених кобольдами по всьому Каз Алґару." }
    t[224723] = { name = "Восковий Згорток зі Шкірою", fen = "A collection of resources found from skinning wildlife.", fua = "Зібрання ресурсів, здобутих оббіловуванням звірини." }
    t[224724] = { name = "Восковий Згорток з Пилом", fen = "A collection of resources from Azj-Kahet containing enchanting supplies.", fua = "Зібрання ресурсів з Аж-Кагету, що містить приладдя для чаротворення." }
    t[224725] = { name = "Восковий Згорток з Травами", fen = "A collection of herbs supplied by the Arathi of Hallowfall.", fua = "Зібрання трав, постачене Араті Голловфолу." }
    t[224726] = { name = "Воскова Коробка з Камінням", fen = "A collection of ore from the nearby earthen mines stuffed into a kobold-crafted box.", fua = "Зібрання руди з довколишніх копалень земельників, напхане в коробку кобольдського виробу." }
    t[224727] = { name = "Трофейна Риба Прудкого", fen = "This fish ain't much good for eatin', but it sure looks nice.", fua = "Із цієї риби їдець нікудишній, та виглядає вона хоч куди." }
    t[224729] = "Зуб Акули Нетрів"
    t[224760] = { name = "Хитунчик", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[224762] = "Бурдюк Дослідника"
    t[224763] = { name = "Креслення: Кубічна Блюзнірка", fen = "Teaches you how to craft Cubic Blasphemia.", fua = "Навчає вас виготовляти Кубічну Блюзнірку." }
    t[224764] = { name = "Нитка з Моховини", fen = "Spun from the wool of the Isle of Dorn's sheep, this thread is both durable and versatile. Sold by Tailoring vendors.", fua = "Спрядена з вовни овець Острова Дорн, ця нитка водночас міцна й універсальна. Продається в торговців кравецьким приладдям." }
    t[224765] = { name = "Вічногорюче Запалення", fen = "Siphoned from your expertise with the forge.", fua = "Видобуто з вашої майстерності біля кузні." }
    t[224767] = { name = "Частини Велетенської Свічки", fen = "The wax here is supposed to be useful to Dagran. Perhaps he'll write a good thesis doctorate on the effects of wax on the bags of adventurers.", fua = "Цей віск мав би стати в пригоді Даґрану. Можливо, він напише гарну докторську дисертацію про вплив воску на торби шукачів пригод." }
    t[224768] = "Креслення Дирижабля Дослідника: Гвинт на Крилі"
    t[224769] = "Креслення Дирижабля Дослідника: Лопаті Ротора"
    t[224770] = "Креслення Дирижабля Дослідника: Передній Гвинт"
    t[224771] = "Креслення Дирижабля Дослідника: Хвостове Оперення"
    t[224772] = { name = "Винагорода від Ґаллівікса", fen = "These orders describe a large bounty available to any of the Darkfuse that discover who is responsible for opening the wall at Opportunity Point.", fua = "Ці накази описують велику винагороду для будь-кого з Темносплаву, хто з'ясує, хто відповідальний за відкриття стіни на Мисі Нагоди." }
    t[224773] = { name = "Червона Свічка Дрібнички", fen = "A candle of deep red wax. You don't want to know how the kobolds got that color.", fua = "Свічка з темно-червоного воску. Ви не хочете знати, як кобольди досягли цього кольору." }
    t[224774] = { name = "Пляшечка Зілля Дрібнички", fen = "A slick, indeterminate liquid coats the inside of this glass bottle.", fua = "Зсередини ця скляна пляшечка вкрита слизькою невизначеною рідиною." }
    t[224775] = { name = "Безсумнівні Рубіни Дрібнички", fen = "A pair of uncut red gems. They seem to be of moderate quality and whether or not they are rubies is unclear.", fua = "Пара необроблених червоних самоцвітів. Вони здаються посередньої якості, а чи це справді рубіни — незрозуміло." }
    t[224777] = { name = "Тіньотворець Сурекі", fen = "Nerubians use these emitters to project orders and messages from their high-ranking leaders.", fua = "Неруби використовують ці випромінювачі, щоб передавати накази й послання своїх високопоставлених очільників." }
    t[224778] = { name = "Збільшувач Дрібнички", fen = "The Enbiggener appears to be an earthen jewel crafting tool, used for magnification purposes.", fua = "Збільшувач, схоже, є інструментом земельників для обробки самоцвітів, що слугує для збільшення." }
    t[224779] = { name = "Череп Алгайнра", fen = "Small leaves and vines sprout from the skull.", fua = "Із черепа проростають дрібні листочки й лози." }
    t[224780] = { name = "Загартована Грозова Шкура", fen = "A particularly rugged pelt that isn't pliable enough to use in crafting. You could study it to learn a thing or two about the local fauna, however.", fua = "Особливо груба шкура, не досить гнучка для ремесла. Утім, її можна вивчити, аби дізнатися дещо про місцеву фауну." }
    t[224781] = { name = "Безодняне Хутро", fen = "A small tuft of fur that carries a deep purple hue. It isn't of much traditional use, but such a fascinating and rare specimen won't be found very often.", fua = "Невеликий жмут хутра насиченого фіолетового відтінку. Особливого вжитку від нього немає, але такий захопливий і рідкісний зразок трапляється нечасто." }
    t[224782] = { name = "Гострий Кіготь", fen = "A small, but extremely sharp talon of a creature. While it isn't big enough to be of practical use, it is fascinating to study.", fua = "Маленький, але надзвичайно гострий кіготь якоїсь істоти. Він замалий, щоб мати практичний зиск, проте вивчати його захопливо." }
    t[224783] = { name = "Скриня Володарського Вбрання", fen = "Only for those with the most exquisite taste.", fua = "Лише для тих, хто має найвишуканіший смак." }
    t[224784] = { name = "Вершинна Схованка", fen = "Weekly cache containing materials for upgrading gear, gold, Adventurer gear, and more.", fua = "Щотижневий сховок із матеріалами для покращення спорядження, золотом, спорядженням шукача пригод тощо." }
