    t[224791] = "Вбрання Золотого Лорда"
    t[224792] = "Вбрання Кривавого Аристократа"
    t[224797] = { name = "Гросбух Зірдо", fen = "The ledger contains deliveries of Black Blood across the Undermine that were approved by Noggenfogger, Trade-Prince of the Steamwheedle Cartel.", fua = "Гросбух містить записи про постачання Чорної Крові по всьому Надкопальню, схвалені Ноггенфоґґером, торговим принцом картелю Стімвідла." }
    t[224799] = { name = "Зілля Нізрека", fen = "A vial of faintly glowing liquid.", fua = "Флакон ледь сяйливої рідини." }
