    t[224807] = "Нотатки Алґарського Чинбаря"
    t[224808] = { name = "Опалова Руда", fen = "Crucial pieces of a lost puzzle.", fua = "Ключові частини втраченої головоломки." }
    t[224809] = "Люлька Земнародженого Слюсаря"
    t[224810] = { name = "Еліксир із Шашеля", fen = "Made from wood-boring worms. Famous in the City of Threads, despite being nigh undrinkable.", fua = "Зроблений із деревогризних червів. Славиться в Місті Ниток, хоча й майже непитний." }
    t[224811] = { name = "Цукрові Гриби", fen = "Kids absolutely love hunting for these sweet delights!", fua = "Діти просто обожнюють полювати на ці солодкі ласощі!" }
    t[224813] = { name = "Свисток на Велику Кішку", fen = "The biggest lynx are always just a whistle away.", fua = "Найбільші рисі завжди лиш за один посвист." }
    t[224814] = { name = "Прив'язані до Загону Чоботи Шукача Пригод", fen = "Contains an Adventurer 4/8 piece of equipment corresponding to your class.", fua = "Містить предмет спорядження Шукача Пригод 4/8 відповідно до вашого класу." }
    t[224815] = { name = "Талісман Полум'я", fen = "The dwindling supply of these is rapidly being exhausted by the Arathor.", fua = "Народ Аратора стрімко вичерпує ці й без того мізерні запаси." }
    t[224816] = { name = "Нерубський Альманах", fen = "Indistinguishable charts and diagrams fill the pages. The only discernable thing seems to be an illustration of seismic waves that outline a tunnel system below.", fua = "Сторінки заповнені нерозбірливими таблицями й діаграмами. Єдине, що можна розгледіти, — це зображення сейсмічних хвиль, що окреслюють систему тунелів унизу." }
    t[224817] = "Нотатки Алґарського Травника"
    t[224818] = "Нотатки Алґарського Шахтаря"
    t[224822] = { name = "Перешукати Брухт", fen = "Rummage through scrap to find parts, forgotten prototypes, and more!", fua = "Порийтеся в брухті, щоб знайти деталі, забуті прототипи та інше!" }
    t[224824] = { name = "Присмеркова Тканина", fen = "A shadow-infused cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.", fua = "Просочена тінню тканина, яку кравці здобувають із гуманоїдів по всьому Каз Алґару. Можна купити й продати на Аукціоні." }
    t[224826] = { name = "Світанкова Тканина", fen = "A light-infused cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.", fua = "Просочена світлом тканина, яку кравці здобувають із гуманоїдів по всьому Каз Алґару. Можна купити й продати на Аукціоні." }
    t[224828] = { name = "Ткацька Тканина", fen = "A sticky cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.", fua = "Липка тканина, яку кравці здобувають із гуманоїдів по всьому Каз Алґару. Можна купити й продати на Аукціоні." }
    t[224831] = { name = "Куб Нескінченних Винаходів (Лише PTR)", fen = "Counts as a samophlange, whatever that is.", fua = "Рахується як самофланж, хай чим би він був." }
    t[224832] = { name = "Вишуканий Сувій Ткацького Полотна", fen = "An artisan bolt of cloth crafted by Tailors. Can be bought and sold on the Auction House.", fua = "Майстерний сувій тканини, виготовлений кравцями. Можна купувати й продавати в Аукціонному домі." }
    t[224833] = { name = "Вишуканий Сувій Ткацького Полотна", fen = "An artisan bolt of cloth crafted by Tailors. Can be bought and sold on the Auction House.", fua = "Майстерний сувій тканини, виготовлений кравцями. Можна купувати й продавати в Аукціонному домі." }
    t[224834] = { name = "Вишуканий Сувій Ткацького Полотна", fen = "An artisan bolt of cloth crafted by Tailors. Can be bought and sold on the Auction House.", fua = "Майстерний сувій тканини, виготовлений кравцями. Можна купувати й продавати в Аукціонному домі." }
    t[224835] = { name = "Коріння Глибогаю", fen = "The roots continue to grow even after the rose is plucked. Not useful for any practical purposes, but rather intriguing to study.", fua = "Коріння продовжує рости навіть після того, як троянду зірвано. Жодного практичного зиску, проте вивчати його доволі цікаво." }
    t[224837] = { name = "Проклята Кирка", fen = "Ancient runes decorate the metal head and trail onto the handle in the form of carved etchings. These patterns become more erratic as they reach the pommel, eventually becoming nothing more than frantic scratches.", fua = "Прадавні руни оздоблюють металеве вістря й тягнуться по руків'ю різьбленими візерунками. Що ближче до набалдашника, то химернішими стають ці узори, врешті обертаючись на самі лиш гарячкові подряпини." }
    t[224838] = { name = "Скалка Порожнечі", fen = "The tiniest sliver of null stone which radiates a pulsing aura of emptiness. It isn't particularly useful for any crafts, but studying it could teach you more about Algari ore and minerals.", fua = "Найдрібніша скалка каменю порожнечі, що випромінює пульсівну ауру пустки. Для ремесел вона особливо не придатна, але, вивчивши її, можна більше дізнатися про алґарські руди й мінерали." }
    t[224839] = { name = "Прив'язані до Загону Наручі Шукача Пригод", fen = "Contains an Adventurer 4/8 piece of equipment corresponding to your class.", fua = "Містить предмет спорядження Шукача Пригод 4/8 відповідно до вашого класу." }
