    t[224852] = { name = "Розтята Торба", fen = "A container spun from The Weaver's master artisans, capable of maximizing the value of cloth as elusive as Dawnweave and Duskweave.", fua = "Вмістище, виткане майстрами-ремісниками Ткалі, здатне сповна розкрити цінність такої рідкісної тканини, як Світанковий і Сутінковий покрив." }
