    t[225343] = { name = "Викривальний Запис у Журналі", fen = "A shimmering stone that fits into a nerubian shadecaster to replay a recorded message.", fua = "Мерехтливий камінь, що вставляється в нерубську тіньопроєкцію, аби відтворити записане послання." }
