    t[225883] = { name = "Підготовлена Рибина-Упир", fen = "Prepared with respect to where it came from and where it's going. Made by chefs when salvaging Cursed Ghoulfish for its fillet. Can be bought and sold on the Auction House.", fua = "Підготовлена з повагою до того, звідки вона походить і куди прямує. Виготовляється кухарями, коли вони обробляють Проклятих Рибин-Упирів на філе. Можна купувати й продавати на Аукціоні." }
