    t[226373] = { name = "Вічний Еліксир Ноггенфоггера", fen = "The color, the smell, the transformations! This elixir is what bards speak of when regaling crowds with tales of the ambrosia of the goblins.", fua = "Колір, запах, перетворення! Цей еліксир — те, про що мовлять барди, коли тішать натовп оповідями про амброзію гоблінів." }
