    t[226380] = { name = "Розклад Працівників", fen = "An extensive list of hours and assignments for Venture employees. A memo from Gallywix is stapled to the bottom.", fua = "Розлогий перелік годин і завдань для працівників Венчурної Компанії. Унизу пришпилена записка від Ґаллівікса." }
    t[226385] = "Окислений Гайковий Ключ"
    t[226391] = { name = "Шкварчливий Клинок-Шокер", fen = "Leaking something dark and viscous. Is that... Black Blood?", fua = "З нього щось темне й тягуче скрапує. Це... Чорна Кров?" }
    t[226393] = { name = "Реактивний Ранець у Коробці", fen = "Warning: Not intended for indoor use. Or outdoor use. If you decide to use our product in any way, that's your problem.", fua = "Попередження: не призначено для використання в приміщенні. Чи поза приміщенням. Якщо ви вирішите використати наш виріб бодай якось, це ваші проблеми." }
    t[226430] = { name = "Мандри Душі", fen = "A short diary of Dawn's Journey.", fua = "Короткий щоденник Подорожі Світанку." }
    t[226505] = "Нерубіанський Самоцвітник"
    t[226507] = { name = "Павутинний Скраб Отруйного Дана", fen = "A venom-base body scrub to remove grime & web build up from Eradicator's Marks. 88% natural flavors!", fua = "Скраб для тіла на основі отрути, щоб усувати бруд і нашарування павутини зі Знаків Винищувача. 88% натуральних ароматів!" }
    t[226508] = { name = "Вплив Візира", fen = "A set of \"official\" paperwork. \"Encourages\" guards in the City of Threads to redirect you to the Royal Apothecary when captured.", fua = "Набір \"офіційних\" документів. \"Спонукає\" вартових у Місті Ниток скерувати тебе до Королівського Аптекаря, коли тебе схоплять." }
    t[226509] = { name = "Прозірливість Генерала", fen = "A copy of Sureki patrols and methods. Allows you to see the detection radius for all guards in the City of Threads.", fua = "Копія патрулів і методів суреків. Дає змогу бачити радіус виявлення всіх вартових у Місті Ниток." }
    t[226510] = { name = "Личина Ткалі", fen = "A pheromonal concoction to fool guards in the City of Threads, significantly reducing their detection radius. A Weaver's specialty.", fua = "Феромонне вариво, щоб ошукати вартових у Місті Ниток, значно зменшуючи радіус їхнього виявлення. Спеціальність Ткалі." }
    t[226511] = { name = "Нерубіморфний Припарок", fen = "A throwable concoction that transforms victims into harmless weave-rats for a short duration. Only works on guards in the City of Threads.", fua = "Метальне вариво, що на короткий час перетворює жертв на нешкідливих ткацьких щурів. Діє лише на вартових у Місті Ниток." }
    t[226512] = "Карта Скарбів: Забутий Меморіал"
    t[226513] = "Карта Скарбів: Розкопки Кагеті"
    t[226514] = "Карта Скарбів: Сховок Ткацьких Щурів"
    t[226515] = "Карта Чуток: Винагороди"
    t[226516] = "Карта Чуток: Зрив"
    t[226517] = "Карта Чуток: Шпигунство"
    t[226518] = { name = "Феро-Втеча", fen = "Throw this implosion of pheromones to stun enemies and disengage from combat. Only works on guards in the City of Threads.", fua = "Кинь цю імплозію феромонів, щоб приголомшити ворогів і вийти з бою. Діє лише на вартових у Місті Ниток." }
    t[226519] = { name = "Досвід Генерала", fen = "A transcribed copy of the combat manual all soldiers in Azj-Kahet study from. When active, allows you to see the detection radius for all guards in the City of Threads.", fua = "Переписана копія бойової настанови, за якою навчаються всі солдати Азж-Кахету. Коли активна, дає змогу бачити радіус виявлення всіх вартових у Місті Ниток." }
    t[226520] = { name = "Феромони Королеви", fen = "The pheromones of the Queen. Obtained discreetly. Guards in the City of Threads will no longer be able to detect you.", fua = "Феромони Королеви. Здобуті непомітно. Вартові в Місті Ниток більше не зможуть вас виявити." }
    t[226521] = "Зміцнена Воскова Обшивка"
    t[226522] = { name = "Уламок Контролера Підриву", fen = "There's some grains of sand caught in the wires.", fua = "У дротах застрягло кілька піщинок." }
    t[226524] = { name = "Частково Заряджений Голосамоцвіт", fen = "Just enough power remaining to be used for a short time.", fua = "Енергії лишилося якраз стільки, щоб ним можна було скористатися недовгий час." }
