    t[226672] = "Перстень Стихійного Хаосу"
    t[226681] = { name = "Шкварчливий Попелястий Пилок", fen = "Causes particularly painful sneezing fits. The meadery has stockpiled quite a bit now thanks to your efforts.", fua = "Спричиняє надзвичайно болісні напади чхання. Завдяки вашим зусиллям медоварня тепер має чималий його запас." }
    t[226683] = { name = "Несправний Мехокостюм", fen = "A machine that has lost its proper form.", fua = "Машина, що втратила належну форму." }
    t[226692] = "Розколотий Камінь"
    t[226695] = { name = "Прихильність Підступного Радника", fen = "Anub'arash wouldn't know wisdom if it stormed the palace! Now, how to get rid of him...", fua = "Ануб'араш не впізнав би мудрості, навіть якби вона взяла палац штурмом! Отож, як його позбутися..." }
    t[226696] = { name = "Прихильність Могутнього Радника", fen = "Here's some wisdom for you, Takazj: Stay out of my way.", fua = "Ось тобі трохи мудрості, Таказдж: не ставай мені на шляху." }
