    t[226814] = { name = "Скриня золота", fen = "Contains 1000 gold.", fua = "Містить 1000 золота." }
    t[226823] = { name = "Автоматичний Гак-Кішка Трюмноводного Картелю", fen = "Usually meant for quickly outranging explosives, but there's nothing in the warranty that says it can't be used for bird-fishing.", fua = "Зазвичай призначений, щоб швидко відскакувати від вибухівки, та в гарантії немає нічого, що забороняло б використовувати його для риболовлі на птахів." }
