    t[226854] = { name = "Зім'ятий Розрахунковий Листок", fen = "Smudged with greasy fingerprints, but you can still make out the employer's address. A note is taped to the back.", fua = "Заляпаний жирними відбитками пальців, але адресу роботодавця ще можна розібрати. До звороту приклеєна записка." }
