    t[227541] = { name = "Боргова Розписка Шахтаря", fen = "Official notation of someone's current debt count to Tarbonara Fizzlecrank. Doodles of explosives in the margins make it difficult to make out the names.", fua = "Офіційний запис поточного боргу когось перед Тарбонарою Фіззлкренк. Намальовані на полях вибухівки ускладнюють розбір імен." }
