    t[227546] = "Збережений Кинджал Мешканця Глибин"
    t[227547] = { name = "Боргова Розписка Кейджея", fen = "It reads, \"Kayjay's debt will mirror his prediliction for creating games with time restrictions. He must work for 74 more years before his debt is absolved.\"", fua = "На ній написано: \"Борг Кейджея відображатиме його схильність створювати ігри з обмеженням часу. Він має пропрацювати ще 74 роки, перш ніж його борг буде погашено.\"" }
    t[227548] = { name = "Боргова Розписка Фантастичного Дейві", fen = "It reads, \"Fantastic Davey's debt will follow his aptitude for bestowing points in every game he makes. Funds earned towards paying his debt off will be worth 0.1x its actual worth.\"", fua = "На ній написано: \"Борг Фантастичного Дейві відповідатиме його хисту нараховувати очки в кожній грі, яку він створює. Кошти, зароблені на погашення його боргу, оцінюватимуться в 0.1x від їхньої справжньої вартості.\"" }
    t[227659] = { name = "Швидкоплинний Таємний Прояв", fen = "A concentrated orb of arcane energy, fit for study by an aspiring enchanter.", fua = "Сконцентрована сфера таємної енергії, придатна для вивчення честолюбним зачаровувачем." }
    t[227661] = { name = "Сяйливий Телуричний Кристал", fen = "A small crystal formed from condensed magical energy. An enchanter could learn much by studying it.", fua = "Маленький кристал, утворений зі стиснутої магічної енергії. Зачаровувач міг би багато чого навчитися, вивчаючи його." }
    t[227662] = { name = "Мерехтливий Пил", fen = "A fine powder that glimmers with arcane magic.", fua = "Дрібний порошок, що виблискує таємною магією." }
    t[227663] = { name = "Рекомендація Ноггенфоггера", fen = "Jo. This putz has no clue what sorta top shelf grub the people of Steamwheedle can make. Cook some food that will blow their socks off. Bonus cred if the socks actually explode.", fua = "Йо. Цей бовдур і гадки не має, який добірний харч уміють готувати люди Стімвідла. Зготуй щось таке, від чого в них шкарпетки злетять. Подвійна повага, якщо шкарпетки й справді вибухнуть." }
    t[227666] = { name = "Картки Відгуків Відвідувачів", fen = "The most popular dish seems to be the Smashed Bilgerodent, topped with Talbuk Peppercheese, served with a Druidic Dreamsalad on the side.", fua = "Найпопулярнішою стравою, схоже, є Товчений Трюмний Гризун, присипаний Перцевим Сиром з Талбука, що подається з Друїдичним Салатом Мрій на гарнір." }
    t[227667] = "Фоліант Алґарійського Зачаровувача"
    t[227668] = { name = "Винагорода дослідника Глибин", fen = "X marks the spot.", fua = "Хрестик позначає те саме місце." }
    t[227669] = "Сувій Телепортації"
    t[227670] = "Бляшанка Каджа'Коли"
    t[227673] = { name = "\"Золота\" Рибка", fen = "A fish. Or it used to be? An optimistic goblin would say that products of Steamwheedle are made of possibilities. Should NOT be bought and sold on the auction house.", fua = "Риба. Чи колись була нею? Гоблін-оптиміст сказав би, що вироби Стімвідла зроблені з можливостей. НЕ варто купувати чи продавати на аукціоні." }
    t[227674] = { name = "Улюблена Сковорода Гобдре", fen = "This is just an average frying pan. Well-worn from use. Maybe Jojo Gobdre can explain what makes it so important.", fua = "Це звичайнісінька сковорода. Добряче зношена від користування. Можливо, Джоджо Гобдре зможе пояснити, чим вона така важлива." }
    t[227675] = { name = "Торбинка Зайвих Трав", fen = "Filled to the brim with high-quality herbs... or perhaps a recipe.", fua = "Напхана по вінця добірними травами... а може, ще й рецептом." }
    t[227676] = { name = "Торбинка з Надлишковою Рудою", fen = "Filled to the brim with high-quality ore... or possibly a recipe.", fua = "Наповнена по вінця високоякісною рудою... або, можливо, рецептом." }
    t[227681] = { name = "Торбинка з Надлишковою Шкірою", fen = "Filled to the brim with high-quality leather... or possibly a recipe.", fua = "Наповнена по вінця високоякісною шкірою... або, можливо, рецептом." }
    t[227682] = { name = "Торбинка з Надлишковою Тканиною", fen = "Filled to the brim with high-quality cloth... or possibly a recipe.", fua = "Наповнена по вінця високоякісною тканиною... або, можливо, рецептом." }
