    t[227708] = { name = "Брила Сирого Каджа'міту", fen = "The raw crystal is a bright, nearly fluorescent yellow. The edges remain jagged and rough.", fua = "Сирий кристал має яскравий, майже флуоресцентний жовтий колір. Краї лишаються зазубреними й шорсткими." }
    t[227710] = { name = "Фоліант Перевтілення: Мохововна", fen = "Teaches Polymorph: Mosswool", fua = "Навчає заклинання Перевтілення: Мохововна." }
    t[227713] = "Виплата Консорціуму майстрів"
    t[227769] = { name = "Удосталь Болтів", fen = "You can never have too many bolts. Used by Khaz Algar engineers to craft the Crowd Pummeler 2-30. Sold by Paxton Bombshell in the Ringing Deeps.", fua = "Болтів багато не буває. Використовуються інженерами Каз Алґару для виготовлення Натовпобабахача 2-30. Продаються Пакстоном Бомбогільзою в Дзвінких Глибинах." }
    t[227770] = { name = "Різнобічні Вертушки", fen = "Labeled 'A' through 'ZZZ'. Used by Khaz Algar engineers to craft the Crowd Pummeler 2-30. Sold by Paxton Bombshell in the Ringing Deeps.", fua = "Маркіровані від «A» до «ZZZ». Використовуються інженерами Каз Алґару для виготовлення Натовпобабахача 2-30. Продаються Пакстоном Бомбогільзою в Дзвінких Глибинах." }
    t[227771] = { name = "Рідина для Поворотників", fen = "Supposedly a critical component for functional headlights. Used by Khaz Algar engineers to craft the Crowd Pummeler 2-30. Sold by Paxton Bombshell in the Ringing Deeps.", fua = "Нібито критично важлива деталь для робочих фар. Використовується інженерами Каз Алґару для виготовлення Натовпобабахача 2-30. Продається Пакстоном Бомбогільзою в Дзвінких Глибинах." }
    t[227772] = { name = "Катаклізмічний Перетворювач", fen = "Hopefully less destructive than the name implies. Used by Khaz Algar engineers to craft the Crowd Pummeler 2-30. Sold by Paxton Bombshell in the Ringing Deeps.", fua = "Сподіваймося, менш руйнівний, ніж натякає назва. Використовується інженерами Каз Алґару для виготовлення Натовпобабахача 2-30. Продається Пакстоном Бомбогільзою в Дзвінких Глибинах." }
    t[227773] = { name = "Удароміцна Обшивка", fen = "Immune to dents but susceptible to punctures. Used by Khaz Algar engineers to craft the Crowd Pummeler 2-30. Sold by Paxton Bombshell in the Ringing Deeps.", fua = "Несприйнятлива до вм'ятин, але вразлива до проколів. Використовується інженерами Каз Алґару для виготовлення Натовпобабахача 2-30. Продається Пакстоном Бомбогільзою в Дзвінких Глибинах." }
    t[227774] = { name = "Дозвіл на Бабахання", fen = "Clearly fake, but who is going to argue? Used by Khaz Algar engineers to craft the Crowd Pummeler 2-30. Sold by Paxton Bombshell in the Ringing Deeps.", fua = "Очевидно підробка, та хто сперечатиметься? Використовується інженерами Каз Алґару для виготовлення Натовпобабахача 2-30. Продається Пакстоном Бомбогільзою в Дзвінких Глибинах." }
