    t[228095] = { name = "Сувій Посиленого Викривлення Часу", fen = "A gift from Lady Jaina Proudmoore. This empowered version of the Time Warp spell does not cause the caster to feel any negative effects when the spell ends.", fua = "Подарунок від леді Джайни Праудмор. Ця посилена версія заклинання Викривлення Часу не завдає тому, хто його застосовує, жодних негативних ефектів, коли заклинання завершується." }
