    t[228196] = { name = "Памфлети проти Даркф'юз", fen = "Extra, extra! Read all about it!", fua = "Сенсація, сенсація! Дізнайтеся про все!" }
    t[228210] = { name = "Уламок Вогнесяйного Рубіну", fen = "A tiny precious gem known to give off the same glow as candlelight.", fua = "Крихітний коштовний самоцвіт, відомий тим, що сяє, мов свічка." }
    t[228215] = { name = "Звіт Джаз", fen = "Schematics, paper reports, and scrawled notes hastily stuffed into an envelope. Unfortunately, Jazz's handwriting is near-illegible. Maybe Kory can read it?", fua = "Креслення, паперові звіти й нашкрябані нотатки, нашвидкуруч запхані в конверт. На жаль, почерк Джаз майже нечитабельний. Можливо, Корі зможе його розібрати?" }
    t[228217] = { name = "Креслення: Цільний Бурштин", fen = "Teaches you how to craft Solid Amber.", fua = "Навчає вас створювати Цільний Бурштин." }
    t[228220] = { name = "Восковий Згорток", fen = "One kobold's junk is another person's...well, junk probably. But sometimes? Treasure!", fua = "Для одного кобольда мотлох, а для іншого... ну, теж мотлох, певно. Але іноді? Скарб!" }
    t[228231] = { name = "Ткацька Тканина", fen = "A sticky cloth sourced by Tailors from humanoids throughout Khaz Algar. Can be bought and sold on the Auction House.", fua = "Липка тканина, яку кравці здобувають із гуманоїдів по всьому Каз Алґару. Можна купити й продати на Аукціоні." }
