    t[228409] = { name = "Солодкі Булочки Валріна", fen = "This package contains several of Valrin's Sweetrolls, and a new set of quills.", fua = "У цьому пакунку кілька солодких булочок Валріна й новий набір пер." }
    t[228411] = { name = "Вінець Цирцеї", fen = "Sea dogs and tale spinners tell stories of a mythical siren that could lure even the stubbornest sailors to a watery grave.", fua = "Морські вовки та оповідачі переказують історії про міфічну сирену, що могла заманити навіть найупертіших моряків у водяну могилу." }
    t[228413] = "Принада на Світлячків"
    t[228414] = { name = "Потерта Проводка", fen = "A damaged engineering part that could be used to create other components. Can be purchased from Engineering suppliers throughout Khaz Algar.", fua = "Пошкоджена інженерна деталь, яку можна використати для створення інших компонентів. Купується в інженерних постачальників по всьому Каз Алґару." }
    t[228415] = { name = "Щоденник Адельгонна", fen = "A worn, dusty journal with a stone binding cut with intricate geometric patterns.", fua = "Потертий запорошений щоденник із кам'яною оправою, вирізьбленою вигадливими геометричними візерунками." }
    t[228416] = { name = "Маніфест Стілвейна", fen = "A folded leaflet hand-written with precise but bold lettering.", fua = "Складений листок, написаний від руки точними, але сміливими літерами." }
    t[228417] = { name = "Аварійний Камінь Здоров'я", fen = "Hastily made, but still just as potent.", fua = "Зроблений нашвидкуруч, та все одно такий же дієвий." }
