    t[228422] = { name = "Рецепт: Делікатес із Рибогуля", fen = "Teaches you how to craft Ghoulfish Delight.", fua = "Навчає вас готувати Делікатес із Рибогуля." }
    t[228423] = { name = "Рецепт: Бадьорість-у-Кроці", fen = "Teaches you how to craft Pep-In-Your-Step.", fua = "Навчає вас готувати Бадьорість-у-Кроці." }
    t[228424] = { name = "Рецепт: Попелястий Нектар", fen = "Teaches you how to craft Cinder Nectar.", fua = "Навчає вас готувати Попелястий Нектар." }
