    t[228449] = { name = "Смачний Залізний Злиток", fen = "Delicious, delicious iron.", fua = "Смачнюще-смачнюще залізо." }
    t[228450] = { name = "Їстівні Мідні Самородки", fen = "Edible to an earthen, at least.", fua = "Їстівні принаймні для земельника." }
    t[228451] = { name = "Смакотний Золотий Злиток", fen = "Gold has a delightfully delicate flavor.", fua = "Золото має чудово витончений смак." }
    t[228452] = { name = "Найглибше, Найтемніше Чорне Чорнило", fen = "Does not mix well with other colors, especially pink.", fua = "Погано змішується з іншими кольорами, особливо з рожевим." }
    t[228453] = { name = "Велетенська Торба Лускотливих Камінців", fen = "Best served with cinderbrew mead.", fua = "Найкраще смакує з жаротрунним медом." }
    t[228454] = { name = "Колекційна Пам'ятна Афіша Просценіуму", fen = "Number 137 of 500.", fua = "Номер 137 із 500." }
    t[228455] = { name = "Сувій Брилової Тканини", fen = "Bouldercloth bolts are too heavy to lift by most races.", fua = "Сувої брилової тканини надто важкі, щоб їх підняли представники більшості народів." }
    t[228456] = { name = "Брилова Тканина", fen = "Bouldercloth is far too heavy to use in tailoring for all but the most sturdy of races.", fua = "Брилова тканина надто важка для шиття, хіба що для найміцніших народів." }
    t[228457] = { name = "Журнал Оцінок Світлоіскри", fen = "Headmaster Fynch's notes and assessment of student traits.", fua = "Нотатки директора Фінча й оцінки рис учнів." }
    t[228458] = { name = "Торба з Брилової Тканини", fen = "This bag is far too heavy for most races to use. At least it won't rip!", fua = "Ця торба надто важка для більшості народів. Зате не порветься!" }
    t[228481] = { name = "Крихітна Глибинна Скойка", fen = "While fathomclams can hold beautifully iridescent pearls, harvesting them is dangerous work. This one is too small to have anything of worth.", fua = "Глибинні скойки можуть ховати прекрасні райдужні перлини, та видобувати їх — небезпечна справа. Ця надто мала, щоб містити щось цінне." }
    t[228482] = { name = "Тріснута Райдужна Перлина", fen = "The cracks in this pearl have made it lose its luster.", fua = "Через тріщини ця перлина втратила свій блиск." }
    t[228483] = { name = "Любовно Вирізьблений Рамоліт", fen = "An artist's whittled interpretation of a ramolith.", fua = "Художня різьблена подоба рамоліта." }
    t[228485] = { name = "Запасний Стругальний Ніж Різьбяра", fen = "This chipped knife is good for whittling softwood sticks and not much else.", fua = "Цей щербатий ніж добре стругає палички з м'якого дерева, а більше ні на що не годиться." }
    t[228487] = { name = "Свіжоопалі Гілки", fen = "Just waiting for the right hands to be made into something special.", fua = "Чекають лише на вправні руки, щоб перетворитися на щось особливе." }
    t[228488] = { name = "Маленька Скляна Ваза", fen = "Earthen glass and earthenware is usually square, not round like most other races.", fua = "Скло й глиняний посуд земельників зазвичай квадратні, а не круглі, як у більшості інших народів." }
    t[228489] = { name = "Модна Настоянка", fen = "A conversation piece more than anything else.", fua = "Радше привід для розмови, ніж щось більше." }
    t[228490] = { name = "Свіже Каміння для Випасу", fen = "These rocks are too bland for earthen, but make perfect ramolith feed.", fua = "Це каміння надто прісне для земельників, зате чудово годиться рамолітам у корм." }
    t[228491] = { name = "Підстилка для Рамоліта", fen = "Ramoliths love sleeping on this.", fua = "Рамоліти обожнюють на цьому спати." }
    t[228492] = { name = "Гострі Рубіни", fen = "Rubies are not for the earthen with a bland palate.", fua = "Рубіни не для земельників із прісним смаком." }
    t[228493] = { name = "Кислі Топазові Шматочки", fen = "The earthen have a time-honored tradition of seeing who can eat the most of these in one sitting.", fua = "У земельників є давня традиція змагатися, хто з'їсть найбільше цих за один присіст." }
    t[228494] = { name = "Хрусткі Кам'яні Льодяники", fen = "Perfect for the earthen with a sweet tooth.", fua = "Ідеально для земельника-ласуна." }
    t[228495] = { name = "Зношений Гончарний Круг", fen = "One can't make pottery without one of these.", fua = "Без такого не зробиш гончарних виробів." }
    t[228496] = { name = "Тріснутий Ліхтар", fen = "This lantern can still give off light, but the cracks make it a safety hazard.", fua = "Цей ліхтар ще може давати світло, але через тріщини він небезпечний." }
    t[228497] = { name = "Іржава Шестерня Повітряного Корабля", fen = "This cog is too rusted to be of any real value.", fua = "Ця шестерня надто іржава, щоб мати хоч якусь справжню цінність." }
