    t[228549] = { name = "Велетенська Брила Каджаміту", fen = "The jagged remains of the Raging Gemsplitter, fractures running through its core.", fua = "Зубчасті рештки Лютого Самоцвіторозкольника, тріщини пронизують саме його осердя." }
    t[228560] = { name = "Давня дивовижа", fen = "An earthen relic that grants power. Could they have been gifts from the titans? Or an invention all their own?", fua = "Земельна реліквія, що дарує силу. Чи були вони дарунками титанів? Чи цілком власним винаходом земельних?" }
    t[228580] = "Ідол Грубої Сили"
    t[228581] = { name = "Давня дивовижа", fen = "Just holding this relic makes you feel swift on your feet. Something the earthen would surely value, given their heavy frames.", fua = "Сама лише ця реліквія в руках змушує почуватися прудким на ногах. Те, що земельні напевно оцінили б, зважаючи на їхню важку статуру." }
    t[228582] = "Обтічна Реліквія"
    t[228608] = { name = "Про Застосування Аратійської Технології до Земельного Життя", fen = "Volume two.", fua = "Том другий." }
    t[228609] = { name = "Запікання Каміння для Чайників", fen = "Twenty recipes to enhance the flavor of your minerals and rocks!", fua = "Двадцять рецептів, щоб посилити смак твоїх мінералів і каменів!" }
