    t[228741] = { name = "Торба Припасів Ліхтарника", fen = "A hastily assembled collection of supplies to aid those brave lights in the dark. May contain gear for your Warband.", fua = "Поспіхом зібрана колекція припасів на допомогу тим відважним вогникам у пітьмі. Може містити спорядження для вашого загону." }
    t[228742] = { name = "Невпізнавана Тканина", fen = "Shredded to bits. It's not enough for a Tailor to use.", fua = "Подерта на клапті. Її замало, щоб придатися кравцеві." }
