    t[228744] = { name = "Скручена Ганчірка Ґобліна", fen = "Unkempt and oily. It's too damaged to be of any use to a Tailor.", fua = "Неохайна й масна. Вона надто пошкоджена, щоб придатися кравцеві." }
    t[228745] = { name = "Волокно Сяйва", fen = "Unrecognizable, but beautiful. It's too damaged to be of any use to a Tailor.", fua = "Невпізнаване, але прекрасне. Воно надто пошкоджене, щоб придатися кравцеві." }
