    t[228918] = { name = "Торба зі Шкірою", fen = "Filled with reagents useful for Khaz Algar Leatherworking.", fua = "Наповнена реагентами, корисними для шкіряної справи Каз Алґару." }
    t[228919] = { name = "Торба з Алґарськими Травами", fen = "Filled with reagents useful for Khaz Algar Alchemy and Inscription.", fua = "Наповнена реагентами, корисними для алхімії та накреслення Каз Алґару." }
    t[228920] = { name = "Торба з Хітином", fen = "Filled with reagents useful for Khaz Algar Leatherworking.", fua = "Наповнена реагентами, корисними для шкіряної справи Каз Алґару." }
    t[228921] = { name = "Надміцний Оздоблювальний Порошок Ґрифти", fen = "Guaranteed to make your equipment outshine any previous embellishments it might have had. Can be bought and sold on the Auction House.", fua = "Гарантовано зробить ваше спорядження кращим за будь-які попередні оздоби, що воно могло мати. Можна купити й продати на Аукціоні." }
    t[228930] = { name = "Оздоблювальна Стрічка", fen = "A smooth ribbon used by Tailors to adorn powerful, intricate equipment. Sold by vendors.", fua = "Гладенька стрічка, якою кравці прикрашають потужне, вишукане спорядження. Продається торговцями." }
    t[228931] = { name = "Торба Алґарського Зачаровувача", fen = "Filled with reagents useful for Khaz Algar Enchanting.", fua = "Наповнена реагентами, корисними для зачарування Каз Алґару." }
    t[228932] = { name = "Торба Алґарського Інженера", fen = "Filled with reagents useful for Khaz Algar Engineering.", fua = "Наповнена реагентами, корисними для інженерії Каз Алґару." }
    t[228933] = { name = "Торба Алґарського Чинбаря", fen = "Filled with reagents useful for Khaz Algar Leatherworking.", fua = "Наповнена реагентами, корисними для шкіряної справи Каз Алґару." }
    t[228940] = { name = "Камінь Повернення Сумнозвісної Нитки", fen = "Return home with the aid of your Severed Threads patrons.", fua = "Повернися додому за допомогою своїх покровителів Розтятих Ниток." }
    t[228942] = { name = "Щедра Скриня", fen = "Contains powerful equipment, a radiant echo, bonus currencies, and a chance at a new or upgraded curio. Requires a Restored Coffer Key to open.", fua = "Містить потужне спорядження, осяйне відлуння, додаткові валюти й шанс на нову чи поліпшену дивовижу. Для відкриття потрібен Відновлений Ключ від Скрині." }
    t[228943] = { name = "Розірвана Нитка Майстра Шпигунів", fen = "The Weaver sends her highest regards.", fua = "Ткаля передає свою найщирішу повагу." }
    t[228944] = { name = "Розірвана Нитка Володаря Склепу", fen = "The General sends his highest honors.", fua = "Генерал передає свою найвищу шану." }
    t[228945] = { name = "Розрубана Нитка Виконавця", fen = "The Vizier sends his highest compliments.", fua = "Візир передає свою найвищу шану." }
    t[228946] = { name = "Ремісничий Стіл Лігва Ткалі", fen = "Bring to Ak'itaz in the Weaver's Lair to have a profession table of your chosing constructed.", fua = "Принесіть до Ак'ітаз у Лігві Ткалі, щоб виготовити ремісничий стіл на ваш вибір." }
    t[228947] = "Ремісничий Стіл Лігва Ткалі"
    t[228948] = { name = "Зменшувальний Промінь Джаз", fen = "The ray gun hums in your hands. Stunningly, it seems stable--despite being held together with rusty bolts and Jazz's hopes and dreams.", fua = "Променева гармата гуде у ваших руках. На диво, вона видається стабільною — попри те, що тримається купи лише на іржавих болтах та надіях і мріях Джаз." }
