    t[228956] = { name = "Відро Мотлоху", fen = "It's got what you need! Sold by vendors.", fua = "У ньому є все, що вам потрібно! Продається торговцями." }
    t[228958] = { name = "Сяйливе відлуння", fen = "Obtained from a Bountiful Coffer in a Bountiful Delve. Bring to a Worldsoul Memory to experience the radiant memories of Azeroth.", fua = "Здобувається зі щедрої скрині у Щедрій Глибині. Принеси його до Спогаду Світодуші, щоб пережити сяйливі спогади Азероту." }
    t[228959] = { name = "Купа Невпізнаного М'яса", fen = "A pile of meat left over from a creature you skinned. It could be from the creature itself, or something it ate. Only one way to find out!", fua = "Купа м'яса, що лишилася від обдертої вами істоти. Воно може бути з неї самої або з того, що вона з'їла. Є лише один спосіб дізнатися!" }
    t[228963] = { name = "Незнайома Емблема", fen = "This handheld badge has a red emblem that looks like the rising sun with long rays emanating from it.", fua = "На цьому ручному значку червона емблема, що нагадує сонце, яке сходить, з довгими променями довкола." }
