    t[229388] = { name = "Шанована Геральдика Бійця", fen = "Acquired from various PvP activities or purchased with Honor from PvP quartermasters in Dornogal. Can be bought and sold on the Auction House.", fua = "Здобувається в різних PvP-заняттях або купується за Честь у PvP-інтендантів у Дорногалі. Можна купувати й продавати на Аукціоні." }
    t[229389] = { name = "Шанована Геральдика Претендента", fen = "Purchased with Honor from PvP quartermasters in Dornogal.", fua = "Купується за Честь у PvP-інтендантів у Дорногалі." }
    t[229390] = { name = "Шанована Геральдика Гладіатора", fen = "Purchased with Conquest from PvP quartermasters in Dornogal.", fua = "Купується за Завоювання у PvP-інтендантів у Дорногалі." }
    t[229392] = { name = "Зім'ятий Накладний Лист", fen = "A letter written to the Underrider Gang detailing payments in the form of weapons.", fua = "Лист до Зграї Глибинних Вершників, де описано оплату у вигляді зброї." }
    t[229401] = { name = "Памфлет Консорціуму Ремісників", fen = "A special notice for eager competitors of all ranks!", fua = "Особливе оголошення для завзятих суперників усіх рангів!" }
    t[229405] = { name = "Ентропійне Ядро", fen = "Condensed energies siphoned from the soil of K'aresh.", fua = "Згущена енергія, витягнута з ґрунту К'ареша." }
    t[229407] = { name = "Лимонна Кислота", fen = "Whether this will improve the taste of grog is up for debate.", fua = "Чи покращить вона смак ґрогу — питання спірне." }
    t[229419] = { name = "Грамота на Бочкодоння", fen = "The deed to Barrelbottom Apartments. Moz won't be needing this anymore.", fua = "Грамота на власність на Апартаменти Бочкодоння. Мозу це більше не знадобиться." }
    t[229420] = { name = "Сфера Аніми", fen = "A tactile ball of anima. It squeaks when you throw it. Animals seem to love it.", fua = "М'ячик з аніми, приємний на дотик. Коли його кидаєш, він пищить. Тварини, схоже, його обожнюють." }
    t[229423] = { name = "Ехо-Дослідник", fen = "A miniature version of cartel Om technology.", fua = "Мініатюрна версія технології картелю Ом." }
    t[229424] = { name = "Анімовисмоктувач", fen = "Apparently there is a portal in the back that leads directly to K'aresh. You've been assured it's safe. Probably.", fua = "Схоже, ззаду є портал, що веде просто до К'ареша. Тебе запевнили, що це безпечно. Мабуть." }
