    t[229805] = { name = "«Вісник Глибнокопальні» Минулого Тижня", fen = "The gutter is a fitting place for this tabloid.", fua = "Стічна канава — належне місце для цього бульварного листка." }
    t[229809] = { name = "Обтяжена Металева Куля", fen = "Suspiciously, it seems to roll towards green colored objects.", fua = "Підозріло, але вона начебто котиться до предметів зеленого кольору." }
    t[229823] = { name = "Каністра Розчину Темного Сплаву", fen = "All-purpose fluid! Use it for anything! Certified inorganic!", fua = "Універсальна рідина! Підходить для чого завгодно! Гарантовано неорганічна!" }
    t[229824] = { name = "Бананова Шкірка", fen = "Think of the comedic potential if you just left it in the street.", fua = "Лише уяви, який комічний потенціал, якщо просто лишити її на дорозі." }
    t[229825] = { name = "Пом'ята Бляшанка Каджа'Коли", fen = "Technically recyclable!", fua = "Формально придатне до переробки!" }
    t[229892] = { name = "Зразок Скла Порожнечі", fen = "Shards of void-infused glass from the surface of K'aresh.", fua = "Скалки просоченого Порожнечею скла з поверхні К'ареш." }
    t[229898] = "Пристрій Захоплення"
    t[229899] = { name = "Уламок ключа від скрині", fen = "Acquired from treasures, Radiant Echos, World Quests, and outdoor events throughout Khaz Algar.", fua = "Здобувається зі скарбів, осяйних відлунь, світових завдань і подій просто неба по всьому Каз Алґару." }
    t[229900] = { name = "Лагідно Виткова Крихта", fen = "This small orb of swirling energy pulses in time with your heartbeat.", fua = "Ця маленька куля виткової енергії пульсує в такт твоєму серцебиттю." }
    t[229901] = { name = "Панцир Кролуска", fen = "The brittle shell of a K'areshi Krolusk.", fua = "Крихкий панцир кролуска з К'ареш." }
    t[229905] = { name = "Торбинка з Насінням", fen = "A satchel of packets, which each bear seeds of various shapes and sizes. Alongside the packets is a neatly folded, handwritten note detailing care and planting instructions.", fua = "Торбинка з пакетиками, у кожному з яких насіння різних форм і розмірів. Поруч із пакетиками лежить акуратно складена рукописна записка з настановами щодо догляду й висаджування." }
