    t[230729] = { name = "Привласнена Азеротська Камера", fen = "Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.", fua = "Має ініціали «W.F.» на звороті. Як Ве'нарі це дістала — загадка." }
