    t[230732] = { name = "Мед", fen = "This honey has come in a suitable receptacle. You know, because you were a sticky mess putting it in there.", fua = "Цей мед налито в годящу посудину. Ну знаєте, бо ви добряче замастилися, поки його туди заливали." }
    t[230770] = { name = "Міцна Скринька з Інструментами", fen = "The metal plate reads \"Property of Bargus\"", fua = "На металевій табличці написано «Власність Барґуса»." }
    t[230771] = { name = "Прототип земельників", fen = "An earthen-crafted device used to detect energy signatures within mineral structures.", fua = "Пристрій земельників, яким виявляють енергетичні сигнатури в мінеральних структурах." }
    t[230772] = { name = "Згущена Енергія Порожнечі", fen = "Void essence gathered from surges amidst the void glass expanse on K'aresh, and coalesced into a tempting lure.", fua = "Сутність Порожнечі, зібрана з виплесків серед обширу склистої Порожнечі на К'ареші та згущена в звабливу принаду." }
    t[230773] = { name = "Перезаряджена Батарея", fen = "Not just charged. Overcharged!", fua = "Не просто заряджена. Перезаряджена!" }
