    t[230809] = { name = "Живець Флори К'ареша", fen = "The fragrance from the K'areshi flora tends to be more tart than many of the plants on Azeroth.", fua = "Аромат флори К'ареша зазвичай терпкіший, ніж у багатьох рослин Азероту." }
    t[230850] = "Глибинобот 7001"
    t[230851] = { name = "Оздоблена Аратійська Скринька", fen = "Several crystalline shards from Hallowfall sit upon a plush pillow within the ornately carved box.", fua = "Кілька кристалічних скалок зі Голловфолу лежать на пухкій подушці всередині майстерно різьбленої скриньки." }
    t[230852] = { name = "Жетон Зброї Шанованого Гладіатора", fen = "Proof of your prowess on the battlefield. Can be exchanged for gladiator weapons at the Contender's Gate in Dornogal.", fua = "Доказ вашої доблесті на полі бою. Можна обміняти на зброю гладіатора біля Брами Суперника в Дорногалі." }
    t[230905] = { name = "Розколота Іскра Удачі", fen = "A fragment of a Spark of Fortunes that can be reformed if combined with another piece. Primarily obtained through weekly caches.", fua = "Уламок Іскри Удачі, який можна відновити, поєднавши з іншою частиною. Здобувається переважно з щотижневих сховків." }
    t[230906] = { name = "Іскра Удачі", fen = "This unique crafting material can help an item achieve expertise beyond that of mortal ability.", fua = "Цей унікальний ремісничий матеріал здатен наділити предмет вправністю, що перевершує можливості смертних." }
    t[230907] = { name = "Стільник", fen = "The K'aresh honey has an unexpected, slightly sour taste with its sweetness.", fua = "Мед із К'арешу має несподіваний, ледь кислуватий присмак за своєю солодкістю." }
    t[230924] = "Матеріалізатор Прожектора 1000"
    t[230931] = { name = "Формула: Зачарований Вивітрений Герб Підкопа", fen = "Teaches you how to create Enchanted Weathered Undermine Crest.", fua = "Навчає вас створювати Зачарований Вивітрений Герб Підкопа." }
    t[230932] = { name = "Формула: Зачарований Рунний Герб Підкопа", fen = "Teaches you how to create Enchanted Runed Undermine Crest.", fua = "Навчає вас створювати Зачарований Рунний Герб Підкопа." }
    t[230933] = { name = "Формула: Зачарований Позолочений Герб Підкопа", fen = "Teaches you how to create Enchanted Gilded Undermine Crest.", fua = "Навчає вас створювати Зачарований Позолочений Герб Підкопа." }
    t[230935] = { name = "Зачарований Позолочений Герб Підкопа", fen = "A magical crest used to infuse crafted equipment to higher levels of power. Can be acquired from Syenite in Dornogal.", fua = "Магічний герб, яким наповнюють виготовлене спорядження до вищих рівнів могутності. Можна придбати в Сієніт у Дорногалі." }
