    t[230986] = { name = "Зароджений Позолочений Герб Підкопа", fen = "A powerful vessel made from Gilded Undermine Crests, ready to be enchanted.", fua = "Могутній посуд, зроблений з Позолочених Гербів Підкопа, готовий до зачарування." }
