    t[231089] = { name = "Листування від Зірдо", fen = "A letter from Zirdo detailing Pamsy's involvement in opening the wall, attracting attention to Gallywix's Black Blood mining. This will prove Zirdo snitched on Pamsy, causing Gozzic to attack her engineers.", fua = "Лист від Зірдо, в якому описано причетність Памсі до відкриття стіни, що привернуло увагу до видобутку Чорної Крові Ґаллівіксом. Це доведе, що Зірдо доніс на Памсі, через що Ґоззік напав на її інженерів." }
