    t[231163] = { name = "Привласнена Азеротська Камера", fen = "Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.", fua = "Має ініціали «W.F.» на звороті. Як Ве'нарі це дістала — загадка." }
    t[231164] = { name = "Гоблінський Гак-Кішка", fen = "Get flying robots to fall for you, hook, line, and sinker.", fua = "Змусь летючих роботів попастися на гачок з усіма тельбухами." }
    t[231173] = { name = "Магнітомех Маестро Брухту", fen = "Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.", fua = "Навчає вас прикликати цього їздового звіра. Цей звір змінюється залежно від вашого вміння верхової їзди та місцеперебування." }
    t[231265] = { name = "Діамант Джастор", fen = "I'm not gonna give you a detailed receipt of all the businesses I took over, started, sold, or destroyed. I won: that's all. I won everything I wanted.", fua = "Я не збираюся давати тобі докладний перелік усіх справ, які я перебрав, заснував, продав чи знищив. Я переміг — ось і все. Я виграв усе, що хотів." }
    t[231266] = "Перфоратор Випадкових Чисел"
    t[231268] = { name = "Вибухолюта Мачете", fen = "The word 'Family' is etched into its hilt.", fua = "На руків'ї викарбувано слово «Родина»." }
    t[231291] = "Радар"
    t[231311] = { name = "Дивовижна Стіна Фронтмена", fen = "It's gonna be the one that saves you.", fua = "Саме вона тебе врятує." }
    t[231369] = { name = "Червоноягода", fen = "If Getry's notes are correct, these plump, red berries should reverse Alice's transformation.", fua = "Якщо нотатки Гетрі правдиві, ці соковиті червоні ягоди мають повернути перетворення Аліси назад." }
    t[231510] = { name = "Ключ від Викривленої в Часі Скрині Реліквій", fen = "Exchangers will trade keys for valuable Blackrock Depths loot at the Bronze Celebration hub in Tanaris. Max of 120 keys.", fua = "Міняйли обміняють ключі на цінну здобич із Чорнокам'яних Глибин на святкуванні Бронзових у Танарісі. Максимум 120 ключів." }
