    t[231756] = { name = "Іскра Зоряного Сяйва", fen = "This unique crafting material can help an item achieve expertise beyond that of mortal ability.", fua = "Цей унікальний ремісничий матеріал здатен наділити предмет вправністю, що перевершує можливості смертних." }
    t[231757] = { name = "Розколота Іскра Зоряного Сяйва", fen = "A fragment of a Spark of Starlight that can be reformed if combined with another piece. Primarily obtained through weekly caches.", fua = "Уламок Іскри Зоряного Сяйва, який можна відновити, поєднавши з іншою частиною. Здобувається переважно з щотижневих сховків." }
    t[231766] = { name = "Ріг Молотопаду", fen = "A Mag'har horn used by outriders to signal others.", fua = "Ріг маг'харів, яким вивідачі подавали сигнали іншим." }
    t[231767] = { name = "Зачарований Вивітрений Астральний Герб", fen = "A magical crest used to infuse crafted equipment to higher levels of power. Can be acquired from Syenite in Dornogal.", fua = "Магічний герб, яким наповнюють виготовлене спорядження до вищих рівнів могутності. Можна придбати в Сієніт у Дорногалі." }
    t[231768] = { name = "Зачарований Позолочений Астральний Герб", fen = "A magical crest used to infuse crafted equipment to higher levels of power. Can be acquired from Syenite in Dornogal.", fua = "Магічний герб, яким наповнюють виготовлене спорядження до вищих рівнів могутності. Можна придбати в Сієніт у Дорногалі." }
    t[231769] = { name = "Зачарований Рунний Астральний Герб", fen = "A magical crest used to infuse crafted equipment to higher levels of power. Can be acquired from Syenite in Dornogal.", fua = "Магічний герб, яким наповнюють виготовлене спорядження до вищих рівнів могутності. Можна придбати в Сієніт у Дорногалі." }
    t[231786] = { name = "Щоденник Уклера", fen = "Disjointed scribbles that document one Hozen's five whimsical visits to the island.", fua = "Безладні нотатки, що описують п'ять химерних відвідин острова одним гозеном." }
    t[231788] = { name = "Пісні Сирени", fen = "Twenty-two pages filled with the same repeating, indecipherable words.", fua = "Двадцять дві сторінки, заповнені тими самими повторюваними, нерозбірливими словами." }
    t[231791] = { name = "Сигіл Спокутника", fen = "Old, but immaculately kept.", fua = "Старий, але бездоганно збережений." }
    t[231802] = { name = "Звіт про Розвідку Компанії Ешвейн", fen = "Records the reckless greed that led Ashvane Co. to ignore safety concerns.", fua = "Свідчить про безрозсудну жадобу, через яку компанія Ешвейн знехтувала питаннями безпеки." }
    t[231804] = { name = "Ігрова Фігурка", fen = "An assorted collection of game pieces.", fua = "Збірка різноманітних ігрових фігурок." }
    t[231809] = { name = "Ключ Першого Помічника Дат-Дата", fen = "Key to Dat-Dat's private stash of reading material.", fua = "Ключ до особистого сховку Дат-Дата з книжками для читання." }
    t[231812] = { name = "Поезія Гозенів", fen = "Includes poems \"Happy Tails\", \"Ookie Eats Rats\" and \"The Dark Abyss\"", fua = "Містить вірші «Щасливі Хвости», «Укі Їсть Щурів» і «Темна Безодня»." }
    t[231813] = { name = "Маніфест Острова Сирен", fen = "Numerous efforts to unfairly divide the spoils plundered from the island.", fua = "Численні спроби несправедливо поділити награбоване на острові." }
    t[231818] = "Чіпкий Вінець Глибин"
    t[231821] = { name = "Саморобна Вибухівка", fen = "These makeshift explosive should do the trick. An explosion is an explosion after all.", fua = "Ця саморобна вибухівка має згодитися. Зрештою, вибух є вибух." }
    t[231822] = "Куртка зі Шкіри Головонога"
    t[231824] = "Вінець Огортаючого Левіафана"
    t[231825] = "Трисерцевий Нагрудник"
    t[231826] = "Наплічники з Гачкуватими Шипами"
    t[231827] = "Латний Нагрудник Гарпунника"
    t[231830] = "Наплічники з Панцира Кракена"
    t[231831] = { name = "Посилка Ве'нарі", fen = "The device emits a quiet, yet steady, trilling.", fua = "Пристрій видає тихе, але рівне дзеленчання." }
    t[231878] = { name = "Доказові Предмети", fen = "These assorted items belong to the various human factions that make up the Red Dawn.", fua = "Ці різноманітні предмети належать різним людським фракціям, що складають Багряний Світанок." }
    t[231879] = { name = "Бандана Дефаянів", fen = "Article of Proof. The signature red bandana worn by the Defias Brotherhood. Old and faded but still vibrant.", fua = "Доказовий предмет. Прикметна червона бандана, яку носить Братство Дефаянів. Стара й вицвіла, але досі яскрава." }
    t[231880] = { name = "Помаранчева Бандана", fen = "Article of Proof. This orange bandana, frequently worn by those affiliated with the Syndicate, stands out against the red of Stromgarde, the Defias, and the Scarlet Crusade.", fua = "Доказовий предмет. Ця помаранчева бандана, яку часто носять прибічники Синдикату, вирізняється на тлі червоного кольору Стромґарда, Дефаянів і Багряного Хрестового Походу." }
    t[231881] = { name = "Емблема Синдикату", fen = "Article of Proof. You've heard rogues used to pickpocket these, but it's much easier to loot off a dead body.", fua = "Доказовий предмет. Ви чули, що розбійники колись витягували їх з кишень, але набагато легше зняти таку з мертвого тіла." }
    t[231883] = { name = "Накидка Багряного Хрестового Походу", fen = "Article of Proof. This tabard doesn't seem as rare as others have made it out to be.", fua = "Доказовий предмет. Цей табард, схоже, не такий уже й рідкісний, як подейкували інші." }
    t[231884] = { name = "Гербова Накидка Стромґарда", fen = "Article of Proof. A tabard worn by soldiers of Stromgarde. Old and tattered, it has not been well cared for.", fua = "Доказовий предмет. Гербова накидка, яку носили вояки Стромґарда. Стара й подерта, доглядали її погано." }
    t[231889] = { name = "Майже Нові Механічні Деталі", fen = "Serviceable parts, if you don't mind a few blemishes and the smell of gunpowder. Adds character, right?", fua = "Придатні деталі, якщо вас не бентежить кілька дефектів і запах пороху. Додає характеру, чи не так?" }
    t[231893] = { name = "Залишки Мастила", fen = "Leftovers from the Underriders. Good for something!", fua = "Недоїдки від Низових Вершників. Десь та й знадобиться!" }
    t[231894] = "Корисний Мотлох"
    t[231895] = { name = "Залишки Безалкогольного Коктейлю", fen = "Still has the little umbrella in it!", fua = "У ньому все ще стирчить маленька парасолька!" }
    t[231896] = { name = "Невикористана Банка", fen = "Were they planning to take up canning?", fua = "Вони збиралися зайнятися консервуванням?" }
    t[231897] = { name = "Іржава Монета", fen = "Has no monetary value. But is useful for chemical reactions.", fua = "Не має грошової цінності. Але корисна для хімічних реакцій." }
    t[231898] = { name = "Промисловий Засіб для Зняття Макіяжу", fen = "Powerful stuff. Can dissolve through the bottom of a garbage can.", fua = "Потужна штука. Може роз'їсти дно сміттєвого бака." }
    t[231899] = { name = "Сміття", fen = "It's just trash.", fua = "Це просто сміття." }
    t[231900] = { name = "Пробне Зілля", fen = "Free sample! Ready to be tossed at a Potential Customer!", fua = "Безкоштовний зразок! Готовий до того, щоб кинути в потенційного клієнта!" }
