    t[232053] = { name = "Електрозалоза", fen = "The glands of these electric eels are perfect for charging depleted batteries.", fua = "Залози цих електричних вугрів ідеально підходять для заряджання виснажених батарей." }
    t[232054] = { name = "Виснажена Батарея Боліда", fen = "These batteries aren't much use until they're recharged.", fua = "Від цих батарей мало користі, поки їх не перезарядять." }
