    t[232427] = { name = "Очерет Горгоа", fen = "Grown from soul-enriched silt, these reeds provide remarkable resistance to the ravages of the Gorgoa River's flow.", fua = "Зрослий зі збагаченого душами мулу, цей очерет напрочуд стійкий до руйнівної течії річки Горгоа." }
