    t[232429] = { name = "Бездоганна Шкіра Пожирача Душ", fen = "With the Mawsworn forces fractured and dwindling, the mighty and imposing Soul-Eater reclaims its throne as the Maw's apex predator.", fua = "Тепер, коли сили Пащевірних розрізнені й тануть, могутній і грізний Пожирач Душ повертає собі трон головного хижака Пащі." }
    t[232432] = { name = "Диск-Конденсатор", fen = "Can be thrown to shrink creatures to a portable size.", fua = "Можна кинути, щоб зменшити істот до зручного для перенесення розміру." }
