    t[232605] = { name = "Громовий Уламок", fen = "While crumbled, the rune remains intact. Occasionally, it hums and snaps with violent energy.", fua = "Хоч руна й розкришилася, вона лишається цілою. Час від часу вона гуде й тріщить шаленою енергією." }
    t[232609] = { name = "Переповнене Ядро Аніми", fen = "A highly valuable concentration of anima formed in the stomach of an oversized devourer.", fua = "Надзвичайно цінне згущення аніми, що утворилося в шлунку величезного пожирача." }
