    t[232917] = { name = "Безлика Маска Спаленого Мосту", fen = "Nothing left but the faint smell of smoke and a memory of eyes watering.", fua = "Не лишилося нічого, крім ледь чутного запаху диму та згадки про сльози в очах." }
    t[232918] = { name = "Безлика Маска Шибайголови", fen = "Only the strongest survive.", fua = "Виживають лише найсильніші." }
    t[232919] = { name = "Безлика Маска Темної Уяви", fen = "Surrender your mind to N'Zoth.", fua = "Віддай свій розум Н'Зоту." }
    t[232920] = { name = "Безлика Маска Стражденного", fen = "Pain grants understanding.", fua = "Біль дарує розуміння." }
    t[232921] = { name = "Безлика Маска Довгої Ночі", fen = "Fear of the unknown is a lesser beings' weakness.", fua = "Страх перед невідомим — слабкість нижчих істот." }
    t[232922] = { name = "Перепродані Товари", fen = "A variety of limited edition souvenirs being resold at an extreme markup.", fua = "Розмаїття сувенірів обмеженого випуску, які перепродають із величезною націнкою." }
    t[232927] = "[DNT] Small Surge Chest"
    t[232928] = "[DNT] Medium Surge Chest"
    t[232929] = "[DNT] Large Surge Chest"
    t[232930] = "Запс Свинцеступ"
    t[232932] = "Булава Бранна Бронзбірда"
    t[232935] = "Руна Вантуса: Визволення Підгорода"
    t[232936] = "Руна Вантуса: Визволення Підгорода"
    t[232937] = "Руна Вантуса: Визволення Підгорода"
    t[232944] = { name = "Етерійний Лист-Попередження", fen = "Don't worry about the bots at the pickup. Last guy spotted an ethereal watchin' us, and it ain't the first. These bots'll make sure no one gets the drop on ya.", fua = "Не переймайся через ботів на точці передачі. Останній хлоп помітив етерійця, що стежив за нами, і це не вперше. Ці боти подбають, щоб ніхто тебе не випередив." }
    t[232978] = "Луї Вогнеруч"
    t[232979] = "Джакс Базікало"
    t[232980] = "Аксель Крадькоступ"
    t[232981] = { name = "GNZ Володар Небес 9000", fen = "That block's got cylinders with 80 millimeter bores and puts out 35,000 horses.", fua = "У цього блока циліндри з діаметром 80 міліметрів, і він видає 35 000 кінських сил." }
    t[232982] = { name = "Стандартна Модель Поззіка", fen = "When the Mirage Raceway was destroyed during the cataclysm, Pozzik needed a new place to refine his craft.\n\n\n\nThe Undermine proved fertile grounds for an automatic revolution.", fua = "Коли Міражні Перегони зруйнувало під час Катаклізму, Поззіку знадобилося нове місце, щоб відточувати своє ремесло.\n\n\n\nАндермайн виявився плідним ґрунтом для автоматичної революції." }
    t[232983] = { name = "Парокип", fen = "They say when it's burned as fuel it releases one hundred times more energy than gold nitro.", fua = "Кажуть, коли його спалюють як паливо, він вивільняє у сто разів більше енергії, ніж золоте нітро." }
    t[232984] = { name = "Ручна Корба", fen = "There's nothing more effcient than some good old elbow grease.", fua = "Немає нічого дієвішого за добру стару силу власних рук." }
    t[232985] = { name = "Гладкі Шини 22H", fen = "Full surface contact for maximum friction.", fua = "Повний контакт поверхні задля найбільшого зчеплення." }
    t[232986] = { name = "GE86 Аванс", fen = "For drivers who like to take long turns at the beach.", fua = "Для водіїв, які полюбляють довгі повороти на пляжі." }
    t[232987] = "Щит Бранна Бронзбірда"
    t[232991] = { name = "Пісня Хвилеріза", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[232992] = { name = "Великі Шматки Комахи", fen = "A very meaty and slimy portion of bug meat.", fua = "Дуже м'ясиста та слизька порція комашиного м'яса." }
    t[233006] = { name = "Контейнер Вельми Прибуткового Шламу", fen = "This stuff smells funky and sloshes around in the container. Maybe don't drop it?", fua = "Ця штука дивно тхне й хлюпотить у контейнері. Може, краще її не впускати?" }
    t[233007] = { name = "Ящик Доволі Прибуткового Шламу", fen = "It doesn't feel that heavy, but definitely has some heft once you lug it around. Yet the burden must continue.", fua = "На вигляд не такий важкий, але напевно має чималу вагу, коли його потягаєш. А проте тягар мусить тривати." }
    t[233008] = { name = "Коробка Дещо Прибуткового Шламу", fen = "These small amounts don't seem like much, but in the big picture they really add up.", fua = "Ці дрібні суми наче й не багато, але загалом таки добряче складаються докупи." }
    t[233009] = { name = "Пилок Вогнецвіту", fen = "This pollen is uncharacteristically warm to the touch.", fua = "Цей пилок незвично теплий на дотик." }
    t[233014] = { name = "Скарбниця Бронзового Святкування", fen = "Weekly cache containing materials for upgrading gear, gold, and more.\n\n\n\nThe first weekly cache you earn each week contains a piece of Champion gear from Blackrock Depths and a Restored Coffer Key. Subsequent caches contain a piece of Veteran gear.", fua = "Щотижнева скриня з матеріалами для поліпшення спорядження, золотом тощо.\n\n\n\nПерша щотижнева скриня, здобута за тиждень, містить предмет спорядження поборника з Глибин Блекрока і Відновлений ключ від реліквієвої скрині. Наступні скрині містять предмет спорядження ветерана." }
    t[233018] = { name = "Збирач Сутності", fen = "Thick metal bars curve around a crackling violet core of energy. The collector thrums and pulses, sending an electric feeling up your arm.", fua = "Товсті металеві прути вигинаються навколо тріскотливого фіолетового осердя енергії. Збирач гуде й пульсує, посилаючи електричне відчуття вгору по руці." }
    t[233021] = { name = "Гак-Хапун 9000", fen = "This gadget will allow you to grab goblins and explosives from a distance!", fua = "Цей пристрій дасть вам змогу хапати ґоблінів і вибухівку на відстані!" }
    t[233022] = { name = "Техніка: Руна Вантуса: Визволення Андермайна", fen = "Teaches you how to craft Vantus Rune: Liberation of Undermine.", fua = "Навчає вас виготовляти Руну Вантуса: Визволення Андермайна." }
    t[233025] = { name = "Велетенська Купа Золота", fen = "This is a real haul! Who knew some nerubians carried this much gold?", fua = "Оце справжня здобич! Хто б міг подумати, що деякі неруби носять при собі стільки золота?" }
    t[233026] = { name = "Джонніна Частка Здобичі", fen = "This might cover Johnny's repair cost.", fua = "Цього може вистачити на Джоннін ремонт." }
    t[233027] = { name = "Улюблена Пискуча Іграшка", fen = "Caked in layers of dust this toy still squeaks gently when squeezed.", fua = "Укрита шарами пилу, ця іграшка все ще тихенько пищить, коли її стиснути." }
    t[233028] = { name = "Вогнемет", fen = "Sometimes, fire is the answer.", fua = "Іноді вогонь — це відповідь." }
    t[233029] = "Тріснуте ядро"
    t[233030] = "Заряджені Кабелі"
    t[233031] = "Цілий Зчіп"
    t[233054] = "Чарівна Куля"
    t[233055] = { name = "Очищувач Трупів", fen = "Melts away those pesky corpses for easy cleaning!", fua = "Розчиняє ці набридливі трупи для легкого прибирання!" }
    t[233056] = { name = "Мармадюк", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[233057] = { name = "Каменешукач Майка", fen = "Teaches you how to summon and dismiss this companion.", fua = "Навчає вас прикликати й відсилати цього улюбленця." }
    t[233058] = { name = "Старосвітський Хвилеріз Совізі", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[233061] = { name = "Камінь у Пляшці", fen = "A big rock surrounded by a glass bottle.", fua = "Великий камінь усередині скляної пляшки." }
    t[233062] = { name = "Кишенькова Піца", fen = "Kept safe in its Venture Co. Pizza Pouch.", fua = "Надійно збережена в піца-торбинці Венчурної Компанії." }
    t[233063] = "Гримотниця Бранна"
    t[233064] = { name = "Бронзовий Гоблінський Хвилеріз", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[233066] = { name = "Радіоактивна Щуряча Голова", fen = "Dripping with blood and glowing dangerously, you hope it's safe enough to stash in your bag.", fua = "Скрапує кров'ю та небезпечно сяє; ви сподіваєтесь, що її можна сховати до торби без шкоди для себе." }
    t[233071] = { name = "Винагорода дослідника Глибин", fen = "Surely, great treasure awaits.", fua = "Безперечно, на тебе чекає великий скарб." }
    t[233113] = { name = "Голова Крокодиліана", fen = "The head reeks of a charnel house, covered in blood and splintered bone.", fua = "Голова тхне трупарнею, вкрита кров'ю та потрощеними кістками." }
    t[233114] = { name = "Голова Капітана", fen = "The head is spongy and briny, soaking the contents of your bag.", fua = "Голова губчаста й солона, просочує вміст вашої торби." }
    t[233118] = { name = "Їжа Навинос з Інконтиненталю", fen = "A carefully wrapped portion of The Incontinental's finest meals.", fua = "Дбайливо запакована порція найкращих страв з Інконтиненталю." }
    t[233186] = { name = "Глушник Хвиль 2000", fen = "A small contraption able to specifically block the Underpin's incoming radio waves, preventing him from listening to his favorite gobcast.", fua = "Невеличкий пристрій, здатний цілеспрямовано блокувати вхідні радіохвилі Старшого Бурильника, не даючи йому слухати улюблений гоб-каст." }
    t[233192] = { name = "Зброя Тіньової Варти", fen = "This scepter emits a dark energy that pulls upon your essence.", fua = "Цей скіпетр випромінює темну енергію, що висмоктує вашу сутність." }
    t[233193] = { name = "Зброя Тіньової Варти", fen = "This blade is inscribed with the last known name of its owner: Betrayer.", fua = "На цьому клинку викарбувано останнє відоме ім'я його власника: Зрадник." }
    t[233194] = { name = "Зброя Тіньової Варти", fen = "The handle feels cold to touch as if it pulls from your life force.", fua = "Руків'я холодне на дотик, наче воно висотує вашу життєву силу." }
    t[233195] = { name = "Розпорошувач Феромонів", fen = "Used to spray pheromones on the creatures in the Oasis. Not to be used on yourself.", fua = "Використовується, щоб бризкати феромонами на істот в Оазисі. Не для застосування на собі." }
    t[233196] = "Креслення Гоблоброда Глибинника: Золотий"
    t[233199] = { name = "Насичене Ентропійне Ядро", fen = "Ultra condensed energies contained in a tiny space.", fua = "Ультраущільнені енергії, вміщені в крихітному просторі." }
    t[233202] = { name = "G.O.L.E.M. Молодший", fen = "After the G.O.L.E.M went berserk, Pitz decided to make something smaller, more precise, and smarter.", fua = "Після того, як G.O.L.E.M. оскаженів, Пітц вирішив зробити щось менше, точніше й розумніше." }
    t[233205] = { name = "Бадьорий Сік", fen = "Results may vary.", fua = "Результати можуть різнитися." }
    t[233210] = { name = "Смердюча Гнилозябра", fen = "A particularly stinky fish. Should not be bought or sold on the auction house.", fua = "Особливо смердюча риба. Не варто купувати чи продавати на аукціоні." }
    t[233222] = { name = "Нуль-Бомба", fen = "These vibrating orbs of volatile Void whisper words of madness and discord.", fua = "Ці вібруючі кулі нестійкої Порожнечі шепочуть слова божевілля й розбрату." }
    t[233246] = { name = "Заляпана Брудом Штукенція", fen = "Something's under all of this gunk. Angelo Rustbin at S.C.R.A.P. Headquarters will be interested in this.", fua = "Щось ховається під усім цим брудом. Анджело Іржобак у штабі S.C.R.A.P. зацікавиться цим." }
