    t[234273] = { name = "Притемнений Кристал", fen = "This cold and dark crystal comes to life with your touch. A faded deep blue glow emanates within it. You can hear a faint song within your mind.", fua = "Цей холодний і темний кристал оживає від вашого дотику. У ньому жевріє тьмяне темно-синє сяйво. У вашому розумі лунає ледь чутна пісня." }
