    t[234327] = { name = "Неспокійний Уламок", fen = "Even shattered, the stone vibrates with a restless energy. Tossing and turning, the stone rattles around in your bags constantly.", fua = "Навіть розколотий, камінь вібрує невгамовною енергією. Він безперестанку перевертається й торохтить у ваших торбах." }
    t[234328] = { name = "Бурхливий Уламок", fen = "While seemingly lifeless, peering at the stone fills your mind with images of vast oceans. Seas with unfathomable depths. A wave of fear washes over you as the sheer volume of it all overwhelms you.", fua = "Хоч камінь і здається неживим, споглядання його сповнює ваш розум образами безмежних океанів. Морів незбагненних глибин. Хвиля жаху накриває вас, коли неосяжність усього цього вас приголомшує." }
