    t[234421] = { name = "Павутинна Бомба", fen = "Totally inert and inconspicuous. Unless of course it's flung at something at high speeds.", fua = "Цілковито інертна та непомітна. Хіба що, певна річ, її жбурнути в когось на великій швидкості." }
    t[234425] = { name = "Забутий Фоліант", fen = "Contains an elusive recipe from the depths of Khaz Algar's dungeons.", fua = "Містить рідкісний рецепт із глибин підземель Каз Алґара." }
    t[234426] = { name = "М'ясо, Тушковане в Каджа'Колі", fen = "The unmistakable smell of Kaja'cola radiates off of this unnervingly lime-green meat.", fua = "Від цього тривожно лаймово-зеленого м'яса струмує безпомилковий запах Каджа'Коли." }
    t[234427] = { name = "Виделка Мега-Меха", fen = "Accessories! A relic of Mega-Mecha Gorilla v0.5.", fua = "Аксесуари! Реліквія Мега-Меха Горили v0.5." }
    t[234430] = { name = "Мастило Мега-Меха", fen = "Viscous liquid keeps Gorillion dexterous. A relic of Mega-Mecha Gorilla v0.2.", fua = "В'язка рідина зберігає спритність Горильйона. Реліквія Мега-Меха Горили v0.2." }
    t[234431] = { name = "Батареї Мега-Меха Горили", fen = "A breakthrough in Gorillion technology, rechargeable batteries! A relic of Mega-Mecha Gorilla v0.4.", fua = "Прорив у горильйонній технології, акумуляторні батареї! Реліквія Мега-Меха Горили v0.4." }
    t[234432] = { name = "Двигун Мега-Меха", fen = "Handcrafted machinery with no chasis to keep it safe. A relic of Mega-Mecha Gorilla v0.1.", fua = "Саморобний механізм без шасі, що захищало б його. Реліквія Мега-Меха Горили v0.1." }
    t[234433] = { name = "Шасі Мега-Меха", fen = "A husk of what was, and a reminder of what could be! A relic of Mega-Mecha Gorilla v0.3.", fua = "Оболонка того, що було, і нагадування про те, що могло б бути! Реліквія Мега-Меха Горили v0.3." }
    t[234443] = { name = "М'ясистий Пайок", fen = "These dry and chewy rations don't seem appealing at all, but apparently snapdragons find them irresistible.", fua = "Ці сухі та жорсткі пайки видаються геть непривабливими, та, схоже, дракоморди їх просто обожнюють." }
    t[234449] = "Підступне Запрошення"
    t[234450] = { name = "Піратська Здобич", fen = "Seems Keg-Leg's crew have been stealing equipment from seasoned adventurers. Contains a random Heroic Nerub-ar Palace equipment.", fua = "Схоже, команда Кеґ-Лега крала спорядження в досвідчених шукачів пригод. Містить випадкове спорядження з Палацу Неруб'ар (Героїчний)." }
    t[234451] = { name = "Крадені Товари", fen = "These are goods the Darkfuse have stolen from throughout Khaz Algar.", fua = "Це товари, які Темноплавні накрали по всьому Каз Алґару." }
    t[234452] = { name = "Нарубані Дрова", fen = "Wood cut from the fallen logs of Azure Span. Its pine scent wafts from your bags.", fua = "Деревина, нарубана з повалених стовбурів Лазурового Пасма. З ваших торб струмує сосновий аромат." }
    t[234453] = { name = "Скринька Матроса", fen = "Seems Keg-Leg's crew have been stealing equipment from novice adventurers. Contains a random piece of equipment for your current loot specialization.", fua = "Схоже, команда Барило-Ноги крала спорядження в новачків-шукачів пригод. Містить випадкову частину спорядження для вашої поточної спеціалізації здобичі." }
    t[234454] = { name = "Дистанційний Телепортер", fen = "Configured to teleport short distances. Supposedly used by the Darkfuse to steal precious goods from inhabitants of Khaz Algar.", fua = "Налаштований на телепортацію на короткі відстані. Подейкують, його використовує Темнозлита Ватага, щоб красти коштовні товари в мешканців Каз Алґара." }
    t[234455] = { name = "Уламки в Плямах Бурі", fen = "The minerals of the Siren Isle contain unique properties influenced by the generations of endless storms.", fua = "Мінерали Острова Сирен мають унікальні властивості, сформовані поколіннями нескінченних бур." }
    t[234456] = { name = "Уламки з Кристалічними Скалками", fen = "Generations of unnatural storms have dispersed crystalline filaments across the region.", fua = "Покоління неприродних бур розсіяли кристалічні волокна по всій окрузі." }
    t[234457] = { name = "Ніж Різника", fen = "A weighty blade made for heavy cuts.", fua = "Важкий клинок, створений для грубих розрубів." }
    t[234466] = { name = "Подертий Молитовний Сувій Араті", fen = "The wear and tear of long distance travel from Hallowfall has left these scrolls brittle and tattered.", fua = "Зношеність від далеких подорожей із Голловфолу зробила ці сувої крихкими та подертими." }
    t[234470] = { name = "Осердя Майстра-Коваля", fen = "The coalesced ember resonates with the inspiration of the forge.", fua = "Сплавлена жарина резонує з натхненням кузні." }
