    t[234717] = { name = "Підривник3000", fen = "Could be single, maybe double, or if you're lucky, TRIPLE explosions!", fua = "Може бути один, можливо, два, а якщо пощастить, ТРИ вибухи!" }
    t[234718] = { name = "Стародавнє Руноване Руків'я", fen = "The visage of a female figure has been engraved into the rune-scripted hilt.", fua = "У руків'я, вкрите рунічними написами, викарбувано лик жінки." }
    t[234719] = { name = "Наруч із Гравіюванням Бурі", fen = "The depiction of a stormy mountain peak has been engraved into the bracer.", fua = "На наручі викарбувано зображення вкритого бурею гірського вершка." }
    t[234720] = { name = "Залишок Пам'яті", fen = "The golden dust-like substance appear to be both spectral and physical in nature.", fua = "Ця золотиста речовина, схожа на пил, видається водночас примарною та матеріальною за своєю природою." }
    t[234722] = { name = "Уламок Різьбленого Каменю", fen = "The stone fragment is all that remains of an ancient stone construct.", fua = "Цей кам'яний уламок — усе, що лишилося від стародавнього кам'яного конструкта." }
    t[234723] = { name = "Порожній Сигіл", fen = "Faded etchings surround a now-empty gem setting in the center of the sigil.", fua = "Вицвілі гравюри оточують тепер порожню оправу для самоцвіту в центрі сигіла." }
    t[234729] = { name = "Сховок Скарбів Андермайна", fen = "Rewards a piece of equipment for your Loot Specialization.", fua = "Винагороджує предметом спорядження для вашої спеціалізації здобичі." }
    t[234731] = { name = "Сховок Скарбів Андермайна", fen = "Rewards a piece of equipment for your Loot Specialization.", fua = "Винагороджує предметом спорядження для вашої спеціалізації здобичі." }
    t[234732] = { name = "Закривавлений Медальйон", fen = "Prized among the Bloodwake, these medallions are worn only by those who've won their first hundred bloody victories.", fua = "Цінований серед Кривавого Сліду, ці медальйони носять лише ті, хто здобув свою першу сотню кривавих перемог." }
    t[234733] = { name = "Ритуальна Чаша Кривавого Сліду", fen = "The shallow ritual bowl is stained with blood-red... pigment, probably.", fua = "Мілка ритуальна чаша заплямована кроваво-червоним... пігментом, мабуть." }
    t[234734] = { name = "Гравійований Питний Ріг", fen = "The depiction of a vrykul vessel assaulted by winged creatures from the sea has been engraved onto the ivory.", fua = "На слоновій кістці вигравіювано зображення врайкульського судна, атакованого крилатими створіннями з моря." }
    t[234735] = { name = "Побитий Ліхтар Врайкулів", fen = "Even the bravest of vrykul refuse to embark on the open sea without their lantern. They believe it wards off the darkness beneath the waves.", fua = "Навіть найхоробріші з врайкулів відмовляються вирушати у відкрите море без свого ліхтаря. Вони вірять, що він відганяє темряву під хвилями." }
    t[234736] = { name = "Сувій, Запечатаний Смолою", fen = "The seachart within depicts the Bloodwake ship routes and the many islands they lay siege to. Strangely, the Siren Isle is marked with a warning indicator.", fua = "Морська карта всередині зображує корабельні маршрути Кривавого Сліду та численні острови, які вони беруть в облогу. Дивно, але Острів Сирен позначено застережним знаком." }
    t[234741] = { name = "Усіляка Механіка", fen = "Spare parts, in good enough shape to be used for a variety of machinery.", fua = "Запасні частини в досить доброму стані, щоб слугувати для різноманітних машин." }
    t[234743] = { name = "Скарбничка Стімвідла", fen = "Contains resonance crystals and a small amount of gold for those who have proven themselves to the Steamwheedle Cartel.", fua = "Містить кристали резонансу та невелику суму золота для тих, хто довів свою відданість Стімвідлу." }
    t[234744] = { name = "Скарбничка Картелю Чорноводдя", fen = "Contains resonance crystals and a small amount of gold for those who have proven themselves to the Blackwater Cartel.", fua = "Містить кристали резонансу та невелику суму золота для тих, хто довів свою відданість Картелю Чорноводдя." }
    t[234745] = { name = "Скарбничка Трюмного Картелю", fen = "Contains resonance crystals and a small amount of gold for those who have proven themselves to the Bilgewater Cartel.", fua = "Містить кристали резонансу та невелику суму золота для тих, хто довів свою відданість Трюмному Картелю." }
    t[234746] = { name = "Скарбничка Картелю Підприємців", fen = "Contains resonance crystals and a small amount of gold for those who have proven themselves to Venture Co.", fua = "Містить кристали резонансу та невелику суму золота для тих, хто довів свою відданість Картелю Підприємців." }
    t[234750] = { name = "Осмінієві Наручі Мірмідона", fen = "The faded sigil of Nazjatar is engraved on the surface, surrounded by the words \"For her Glory\".", fua = "На поверхні вигравіювано вицвілий сигіл Назджатар, оточений словами «За її Славу»." }
    t[234751] = { name = "Хвостова Стрічка, Оздоблена Перлами", fen = "Arcane runes flicker across the prismatic surface of the pearl.", fua = "Магічні руни мерехтять на призматичній поверхні перлини." }
    t[234752] = { name = "Поцяткований Коралами Камінь Видіння", fen = "The stone may be inert but the magic that once imbued it lingers faintly. It appears to have been used recently.", fua = "Камінь може бути неактивним, та магія, що колись наповнювала його, ще слабко жевріє. Схоже, ним користувалися нещодавно." }
    t[234753] = { name = "Тріснутий Скіпетр Віщування", fen = "Before it was damaged, this scepter appears to have been attuned specifically to the crystals and ore of the Siren Isle.", fua = "Перш ніж зазнати ушкоджень, цей скіпетр, схоже, був налаштований саме на кристали та руду Острова Сирен." }
    t[234754] = { name = "Закривавлений Амулет Сирени", fen = "The bloodied, ornate face of the pendant have been shattered by something heavy and sharp.", fua = "Закривавлене, вишукане лице амулета було розтрощене чимось важким і гострим." }
    t[234815] = { name = "Зразок Чуми", fen = "A thoroughly vile plague sample. It bubbles and oozes with malice.", fua = "Геть бридкий зразок чуми. Він булькає й сочиться злобою." }
    t[234816] = { name = "Переповнений Мішок Заліза", fen = "Bursting with a light from a dense heap of Flame-Blessed Iron inside.", fua = "Сяє світлом від щільної купи Заліза, Благословенного Полум'ям, усередині." }
    t[234821] = "Улюблена Ключка Татка"
    t[234944] = { name = "Сутність Озлоблення", fen = "This coagulated lump jiggles slightly as you place it in your bag, like jelly. Plague jelly.", fua = "Цей згорнутий згусток злегка тремтить, коли ви кладете його в торбу, наче желе. Чумне желе." }
    t[234950] = "Атомний Регоблінатор"
    t[234951] = "Невідкриті Холодні Напої"
    t[234970] = { name = "Частково Розряджена Батарея", fen = "It still has some juice left.", fua = "У ній ще лишилося трохи соку." }
    t[234971] = { name = "Брила Зарядженого Скла", fen = "After years in the water, this glass holds a significant charge.", fua = "Пробувши роками у воді, це скло утримує значний заряд." }
    t[234972] = { name = "Послання Кривавого Сліду", fen = "The blood-red wax seal bears the mark of the Bloodwake.", fua = "Кроваво-червона воскова печатка несе знак Кривавого Сліду." }
    t[234973] = { name = "Перлинний Футляр для Сувоїв", fen = "Embellished with elegant script, the ornate scroll case has been carved from a single conical seashell.", fua = "Оздоблений елегантним письмом, цей вишуканий футляр для сувоїв вирізьблено з єдиної конічної мушлі." }
    t[235015] = { name = "Пробуджений Ящик Припасів", fen = "Contains important items necessary for an earthen expedition.", fua = "Містить важливі речі, потрібні для експедиції земельників." }
    t[235016] = { name = "Модуль Передислокації", fen = "Warning: Keep all necessary limbs and equipment inside the redeployment radius at all times.", fua = "Увага: завжди тримайте всі необхідні кінцівки та спорядження в межах радіуса передислокації." }
    t[235017] = { name = "Сяйлива Скалка Сховища", fen = "Within the depths of the energized shard, the faint reflection of a metallic face can be seen staring back at you.", fua = "У глибині наснаженої скалки можна побачити тьмяне віддзеркалення металевого обличчя, що дивиться на вас у відповідь." }
    t[235018] = { name = "Відкритий Холодний Напій", fen = "Looks like someone got here before you!", fua = "Схоже, хтось дістався сюди раніше за вас!" }
    t[235037] = { name = "Зім'яте Креслення: Генератор Червоточин: Андермайн", fen = "All that remains of a twice-baked but half-finished idea.", fua = "Усе, що лишилося від двічі переробленої, але недоробленої ідеї." }
    t[235038] = { name = "Зім'яте Креслення", fen = "True brilliance illustrated by coffee stains, cigar burns, and a doodle of a cowboy.", fua = "Справжню геніальність ілюструють плями від кави, опіки від сигар і намальований нашвидкуруч ковбой." }
    t[235041] = "Вінець Цирцеї"
    t[235042] = "Феєрверк На Межі Вибуху"
    t[235050] = { name = "Стіл-у-Коробці", fen = "Guaranteed to include your very own office desk and extra-comfortable lounge chair! Accessories may vary. Patent pending by H.G.", fua = "Гарантовано містить ваш власний робочий стіл і надзвичайно зручне крісло для відпочинку! Аксесуари можуть відрізнятися. Патент очікує на розгляд від Г.Ґ." }
    t[235051] = { name = "Зібрана Енергія", fen = "Crackling with pure energy, this orb flashes with an internal light.", fua = "Тріщачи від чистої енергії, ця куля спалахує внутрішнім світлом." }
    t[235053] = "Завершений Список C.H.E.T.T."
