    t[235533] = { name = "Прототип Авторекламувача", fen = "Comes preloaded with a minimal suite of ads. Get YOUR personal brand recognized in style!", fua = "Постачається з мінімальним набором реклами. Зробіть ВАШ особистий бренд упізнаваним зі смаком!" }
    t[235534] = { name = "Випробна Модель Електропунктури", fen = "Lookin' to increase stress and tension in your life? Look no further!", fua = "Хочете більше стресу й напруги у своєму житті? Не шукайте далі!" }
    t[235535] = { name = "Непомітно Запакований Винахід", fen = "Ain't no solution like a Darkfuse Solution. Wait, that's a pretty good slogan. Write that down!", fua = "Немає кращого рішення, ніж Темнопальне Рішення. Стоп, та це ж непогане гасло. Запишіть!" }
    t[235546] = { name = "Вирвана Сторінка Щоденника", fen = "This page is barely legible and badly weathered. It seems to have been out in the elements for a long time.", fua = "Ця сторінка ледь читається й сильно потерта. Схоже, вона довго пролежала просто неба." }
    t[235548] = { name = "Схованка Сухопутника-земельника", fen = "Contains a piece of Champion gear.", fua = "Містить предмет спорядження Чемпіона." }
    t[235549] = { name = "Багряний Шматувальний Танк", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[235558] = { name = "Коробка з Усячиною Темнопалів", fen = "Darkfuse Solutions will be glad to give this to you in exchange for your Market Research.", fua = "«Темнопальні Рішення» залюбки віддадуть вам це в обмін на ваше Дослідження Ринку." }
    t[235559] = { name = "Прихований Скарб", fen = "Contains powerful equipment, bonus currencies, and a new or upgraded curio. For the Trove to appear, 100 Bounty's Remnants, obtained from completing bountiful delves are required. It's contents depend on the completed Delve's Tier.", fua = "Містить потужне спорядження, додаткові валюти й нову чи покращену дивовижу. Щоб Скарб з'явився, потрібно 100 Решток Здобичі, отриманих за проходження щедрих заглибин. Його вміст залежить від рівня пройденої Заглибини." }
    t[235607] = "Брила досвіду супутника"
    t[235610] = { name = "Сховок Загартованого Шукача Пригод", fen = "Weekly cache containing materials for upgrading gear, gold, Adventurer gear, and more.\n\n\n\nThe first four weekly caches you earn each week contain Coffer Key Shards.", fua = "Щотижнева скриня з матеріалами для поліпшення спорядження, золотом, спорядженням шукача пригод тощо.\n\n\n\nПерші чотири щотижневі скрині, здобуті за тиждень, містять Уламки ключа від реліквієвої скрині." }
