    t[235628] = { name = "Винагорода дослідника Глибин", fen = "Chance to receive a Delver's Bounty from a Bountiful delve's Heavy Trunk. Using this rare map will lead you to a Hidden Trove containing powerful equipment, bonus currencies, and a new or upgraded curio. Obtainable once per week per character.", fua = "Дає шанс отримати винагороду дослідника зі скрині щедрої вилазки. Ця рідкісна мапа приведе вас до прихованої схованки, що містить могутнє спорядження, додаткові валюти й нову чи покращену дивовижу. Можна отримати раз на тиждень на персонажа." }
    t[235639] = { name = "Сховок Загартованого Шукача Пригод", fen = "Weekly cache containing materials for upgrading gear, gold, Adventurer gear, and more.\n\n\n\nThe first four weekly caches you earn each week contain Coffer Key Shards.", fua = "Щотижнева скриня з матеріалами для поліпшення спорядження, золотом, спорядженням шукача пригод тощо.\n\n\n\nПерші чотири щотижневі скрині, здобуті за тиждень, містять Уламки ключа від реліквієвої скрині." }
