    t[235997] = { name = "Бурдюки Дворфського Міцного Пива", fen = "Stolen Ironforge Supplies. There's a note: 'Don't drink this all yourself, Bertram! Stay safe.'", fua = "Викрадені припаси Айронфорджа. Тут є записка: \"Не випивай усе сам, Бертраме! Бережи себе.\"" }
    t[235998] = { name = "Пакунки Кров'янки", fen = "Stolen Ironforge Supplies. 'Expiration Date: when it tastes bad.'", fua = "Викрадені припаси Айронфорджа. \"Термін придатності: доки не зіпсується смак.\"" }
    t[235999] = { name = "Зв'язка Важких Шовкових Бинтів", fen = "Stolen Ironforge Supplies. This bundle of bandages looks twenty years old, but still useable.", fua = "Викрадені припаси Айронфорджа. Ця зв'язка бинтів виглядає на двадцять років, але все ще придатна." }
    t[236000] = { name = "Набір Важких Наборів для Броні", fen = "Stolen Ironforge Supplies. 'Proudly made in the Badlands from genuine billy goat leather.'", fua = "Викрадені припаси Айронфорджа. \"З гордістю виготовлено в Пустках зі справжньої цапиної шкіри.\"" }
    t[236001] = { name = "Бляшанки Озерної Шаленості", fen = "Stolen Ironforge Supplies. 'Sustainably farmed and responsibly canned in Loch Modan!'", fua = "Викрадені припаси Айронфорджа. \"Вирощено сталим способом і відповідально законсервовано в Лох-Модані!\"" }
    t[236003] = { name = "Ткач Долі", fen = "Barely legible words are inscribed on the handle. \"The ritual site lies in Azj-Kahet overlooking the Salien Gutters, far North of Rak-Zakaz.\"", fua = "На руків'ї викарбувано ледь читні слова: \"Місце ритуалу лежить в Азж-Кагеті, над Салієнськими Стоками, далеко на північ від Рак-Заказа.\"" }
    t[236096] = { name = "Уламок ключа від скрині", fen = "Acquired from treasures, Radiant Echoes, World Quests, and outdoor events throughout Khaz Algar.", fua = "Здобувається зі скарбів, Сяйних Відлунь, світових завдань та подій просто неба по всьому Каз Алґару." }
