    t[236406] = { name = "Привласнена Камера S.E.L.F.I.E.", fen = "This looks to be the same camera you use for documenting the wildlife, down to the eteched \"W.F.\" initials.", fua = "Схоже, це та сама камера, якою ти користуєшся для документування дикої природи, аж до вигравіруваних ініціалів «W.F.»." }
    t[236407] = { name = "Самоцвіт Згуби Порожнечі", fen = "A prized item, frequently used in illicit activities.", fua = "Цінний предмет, який часто використовують у незаконних оборудках." }
    t[236411] = { name = "Матриця Мани", fen = "A triangular object made from glass and metal, within which a milky essence whirls.", fua = "Трикутний предмет зі скла й металу, всередині якого вирує молочна сутність." }
    t[236412] = { name = "\"Вогнетривкий\" Пунш", fen = "Common side effects include goosebumps, tremors, and mild nausea.", fua = "Серед поширених побічних ефектів — мурашки по шкірі, тремтіння і легка нудота." }
    t[236413] = { name = "\"Ударостійка\" Газованка", fen = "Common side effects include hot flashes, sweating and mild nausea.", fua = "Серед поширених побічних ефектів — припливи жару, пітливість і легка нудота." }
