    t[238903] = { name = "Привласнена Азеротська Камера", fen = "Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.", fua = "Має ініціали «W.F.» на звороті. Як Ве'нарі це дістала — загадка." }
    t[238904] = { name = "Анімовисмоктувач", fen = "Apparently there is a portal in the back that leads directly to K'aresh. You've been assured it's safe. Probably.", fua = "Схоже, ззаду є портал, що веде просто до К'ареша. Тебе запевнили, що це безпечно. Мабуть." }
    t[238905] = { name = "Диск-Конденсатор", fen = "Can be thrown to shrink creatures to a portable size.", fua = "Можна кинути, щоб зменшити істот до зручного для перенесення розміру." }
    t[238906] = { name = "Привласнена Азеротська Камера", fen = "Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.", fua = "Має ініціали «W.F.» на звороті. Як Ве'нарі це дістала — загадка." }
    t[238907] = { name = "Сфера Аніми", fen = "A tactile ball of anima. It squeaks when you throw it. Animals seem to love it.", fua = "М'ячик з аніми, приємний на дотик. Коли його кидаєш, він пищить. Тварини, схоже, його обожнюють." }
    t[238908] = { name = "Привласнена Азеротська Камера", fen = "Has the initials \"W.F.\" on the back. How Ve'nari got this is a mystery.", fua = "Має ініціали «W.F.» на звороті. Як Ве'нарі це дістала — загадка." }
    t[238909] = { name = "Анімовисмоктувач", fen = "Has a portal in the back of the gun. Used to go to K'aresh, but now who knows where? Not here at least.", fua = "На задньому боці рушниці є портал. Колись він вів на К'ареш, та хто тепер знає, куди? Принаймні не сюди." }
    t[238910] = { name = "Ласо", fen = "A piece of rope tied into a lasso. Nothing fancy about it.", fua = "Мотузка, зав'язана в ласо. Нічого особливого." }
    t[238911] = { name = "Розпорошувач Феромонів", fen = "Used to spray pheromones on the creatures in the Oasis. Not to be used on yourself.", fua = "Використовується, щоб бризкати феромонами на істот в Оазисі. Не для застосування на собі." }
    t[238912] = { name = "Заспокійливий Дротик", fen = "Tranquilizes anything it's thrown at by temporarily disrupting their spiritual web. Non-invasive and pain-free. Apparently a common prank to pull on unsuspecting friends.", fua = "Присипляє будь-кого, в кого його кинуто, тимчасово порушуючи його духовну павутину. Не завдає шкоди й болю. Схоже, поширений жарт, який утинають з нічого не підозрюючими друзями." }
    t[238913] = { name = "Диск-Конденсатор", fen = "Can be thrown to shrink creatures to a portable size.", fua = "Можна кинути, щоб зменшити істот до зручного для перенесення розміру." }
    t[238914] = { name = "Заспокійлива Флейта Гемета", fen = "The snakes are agitated. Ye need tae sooth 'em with yer mad flute skills.", fua = "Змії стривожені. Тре' заспокоїти їх своєю шаленою грою на флейті." }
    t[238915] = { name = "Сфера Аніми", fen = "A tactile ball of anima. It squeaks when you throw it. Animals seem to love it.", fua = "М'ячик з аніми, приємний на дотик. Коли його кидаєш, він пищить. Тварини, схоже, його обожнюють." }
    t[238916] = { name = "Анімовисмоктувач", fen = "Has a portal in the back of the gun. Used to go to K'aresh, but now who knows where? Not here at least.", fua = "На задньому боці рушниці є портал. Колись він вів на К'ареш, та хто тепер знає, куди? Принаймні не сюди." }
    t[238920] = { name = "Сяйлива Емблема Служіння", fen = "A token of gratitude for combatting the Sureki. Can be exchanged for gear at Morgaen's Tears.", fua = "Знак вдячності за боротьбу проти Сурекі. Можна обміняти на спорядження біля Сліз Морґейн." }
    t[238922] = { name = "Креслення: Пантера з Кристалу Порожнечі", fen = "Teaches you how to craft the Void-Crystal Panther.", fua = "Навчає тебе, як виготовити Пантеру з Кристалу Порожнечі." }
    t[238924] = { name = "Прив'язана до Порожнечі Сфера Таємниці", fen = "Found on Big Keech.", fua = "Знайдено на Великому Кічі." }
    t[238933] = { name = "Привласнена Камера S.E.L.F.I.E.", fen = "This looks to be the same camera you use for documenting the wildlife, down to the etched \"W.F.\" initials.", fua = "Скидається на ту саму камеру, якою ви знімаєте дику природу, аж до викарбуваних ініціалів «W.F.»." }
    t[238946] = { name = "Лист від Барило-Ноги", fen = "Your Cut of the Spoils", fua = "Твоя частка здобичі" }
    t[238986] = { name = "Містер Менс", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[239004] = { name = "Торбина Осяйної Служби", fen = "An offering from the highest ranking members of Flame's Radiance for successfully fending off the Sureki forces. Contains Resonance Crystals and a token to redeem for equipment at Morgaen's Tears.", fua = "Дарунок від найвищих очільників Сяйва Полум'я за успішне відбиття сил Сурекі. Містить кристали резонансу та жетон для обміну на спорядження біля Сліз Морґаен." }
    t[239007] = "Підступний Стяг"
    t[239018] = "П'єдестал Переможця"
    t[239019] = { name = "Торба Злих Кульок", fen = "Teaches you how to summon this companion.", fua = "Навчає тебе викликати цього супутника." }
    t[239020] = { name = "Ласощі Тираннотора", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[239074] = { name = "Принада Порожнечі", fen = "These orbs can contain and release void energy, acting as both lure and repository depending on the need.", fua = "Ці сфери можуть вміщати й вивільняти енергію Порожнечі, правлячи водночас за принаду й за сховище, залежно від потреби." }
