    t[239105] = { name = "Незвичні Самоцвіти", fen = "A pair of gems with facets cut to resemble snake eyes. Found in Horrific Visions.", fua = "Пара самоцвітів, чиї грані виточено на подобу зміїних очей. Трапляються в Жахливих Видіннях." }
    t[239106] = { name = "Онікс, Наповнений Тінню", fen = "A gem of unusual hue. Found in Horrific Visions.", fua = "Самоцвіт незвичного відтінку. Трапляється в Жахливих Видіннях." }
    t[239107] = { name = "Злиток, Наповнений Чорною Кров'ю", fen = "It seems like it could be alive. Found in Horrific Visions.", fua = "Здається, наче він може бути живим. Трапляється в Жахливих Видіннях." }
