    t[240216] = { name = "Резонансний Камінь К'арешів", fen = "This striking stone proves that nature's beauty persists even in a wasteland. Sometimes gathered by players with the Mining skill from K'areshi ore deposits. Can be traded in Tazavesh or bought and sold on the Auction House.", fua = "Цей разючий камінь доводить, що краса природи живе навіть у пустці. Іноді його добувають гравці з умінням гірництва з рудних покладів К'арешу. Можна обміняти в Тазавеші або купувати й продавати на аукціоні." }
    t[240932] = { name = "Пакунок Рунованих Гербів Терреміну", fen = "The magic of these crests has expired, rendering them simple decoration now.", fua = "Магія цих гербів вичерпалася, тож тепер вони лише проста прикраса." }
