    t[241616] = { name = "Підпора", fen = "Defeating The Underpin may reward equipment, recipes, currencies, collectibles, and curios.", fua = "За перемогу над Підпорою можна отримати спорядження, рецепти, валюту, колекційні речі та дивовижки." }
    t[241632] = { name = "Героїчна Воскова Фігурка", fen = "A carefully carved and sculpted wax blob that Skibbles made to resemble you. It's clear she worked very hard on it, even though it's hard to tell where the face is.", fua = "Дбайливо вирізьблений і виліплений восковий згусток, який Скібблз зробила схожим на вас. Видно, що вона дуже старалася, хоч і важко вгадати, де тут обличчя." }
    t[241633] = { name = "Крихітна Декоративна Ракета", fen = "When the little crank is wound, the miniature tin rocket makes a faint whirring sound and a wooden exhaust flame gently spins. A simple depiction of a small nerubian and a stick figure is scratched into one of the rocket fins.", fua = "Коли крутнути маленьку корбу, мініатюрна бляшана ракета тихо дзижчить, а дерев'яне полум'я з сопла плавно обертається. На одному з її стабілізаторів видряпано просте зображення малого неруба та чоловічка з паличок." }
    t[241635] = { name = "Латаний Клапоть Павучого Шовку", fen = "This small poorly woven square seems to depict both nerubian and Arathi-inspired patterns. It has your initials crudely stitched in one corner.", fua = "Цей маленький недбало зітканий клапоть, здається, поєднує і нерубські, і араті взори. У кутку грубо вишито ваші ініціали." }
    t[241636] = { name = "Намисто з Грозового Скла та Пера", fen = "One single electric blue stormrook feather dangles gently between two fragments of Storm Glass. A small, rusty Undermine minted nut and bolt act as the clasp.", fua = "Одне-єдине електрично-синє перо грозового крука ніжно гойдається між двома уламками грозового скла. Маленькі іржаві гайка з болтом терремінського карбування правлять за застібку." }
