    t[248013] = { name = "Рецепт: Тарілка Дорнічного Каменю та Сиру", fen = "Teaches you how to craft Dornic Mine and Cheese Platter. This is a decorative item and cannot be eaten.", fua = "Навчає вас готувати тарілку дорнічного каменю та сиру. Це декоративний предмет, його не можна їсти." }
    t[248017] = { name = "Верескливий Кварц", fen = "Named after the subliminal sound the stone produces when held out in the open. The frequencies of which disrupts mana flow, making it extremely uncomfortable for those with greater attunement to mana.", fua = "Названий через приглушений звук, який видає камінь, коли його дістати на відкритому повітрі. Його частоти порушують потік мани, що вкрай неприємно для тих, хто має більшу чутливість до мани." }
    t[248126] = { name = "Початковий набір дослідника Глибин", fen = "Contains a Restored Coffer Key and some consumables.", fua = "Містить Відновлений Ключ від Скрині та кілька витратних предметів." }
    t[248127] = { name = "Косметична торба-сюрприз дослідника Глибин", fen = "Contains a random delve cosmetic for your warband.", fua = "Містить випадковий косметичний предмет Глибин для твоєї бойової ватаги." }
    t[248129] = { name = "Повернуте Спорядження Бранна", fen = "Plenty of clothing, thankfully, but not a curio to be seen.", fua = "Купа одягу, на щастя, але жодної дивовижі на видноті." }
    t[248142] = { name = "Винагорода дослідника Глибин", fen = "Surely, great treasure awaits.", fua = "Безперечно, на тебе чекає великий скарб." }
