    t[257894] = { name = "Соснове Яблуко", fen = "Smooth and creamy once you break past its outer shell. Not to be confused with pineapple.", fua = "М'яке й вершкове, щойно пробитися крізь зовнішню шкаралупу. Не плутати з ананасом." }
    t[257903] = { name = "Стиглий Баштовий Салат", fen = "Laborious to cut due to its size. The taste more than makes up for it though.", fua = "Через свій розмір він важко ріжеться. Та смак це з лишком надолужує." }
    t[258188] = { name = "Шестерногриз Mk. 11", fen = "Teaches you how to summon this mount.", fua = "Навчає тебе викликати цього їздового." }
    t[260173] = { name = "Кристалізований Манопотік Світанкового Сяйва", fen = "Grants one Dawnlight Manaflux capable of imbuing armor with incredible power at the Catalyst in Silvermoon.", fua = "Дарує один Манопотік Світанкового Сяйва, здатний наповнити броню неймовірною силою біля Каталізатора в Срібнолунні." }
    t[264348] = { name = "Вільний Манавирм", fen = "Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location.", fua = "Навчає викликати цей засіб пересування. Цей засіб пересування змінюється залежно від вашої навички верхової їзди та місцезнаходження." }
    t[267045] = { name = "Тремтливе Яйце", fen = "This cobra egg shudders slightly in your hand.", fua = "Це яйце кобри ледь здригається у твоїй руці." }
    t[267233] = { name = "Намисто із Засушених Тролячих Очей", fen = "These eyeballs are shriveled and threaded through with a troll ligament that doubles as a string. If you look closely, you think you can see the pupils slowly expanding and contracting.", fua = "Ці зморщені очні яблука нанизані на тролячу жилу, що править за нитку. Якщо придивитися, здається, ніби зіниці повільно розширюються й звужуються." }
