    t[267628] = { name = "Фоліант Історика", fen = "Contains detailed notes and diagrams on various historical subjects.", fua = "Містить докладні нотатки й діаграми на різні історичні теми." }
    t[267650] = { name = "Навчальний Посібник Кривавих Лицарів", fen = "Contains Blood Knight scriptures and creeds written in ruby colored ink.", fua = "Містить писання й кредо Кривавих Лицарів, написані рубіново-червоним чорнилом." }
    t[267652] = { name = "Молитовник Зброєносця Срібної Руки", fen = "Contains transcribed prayers, hymns and detailed commentary on the Holy Light.", fua = "Містить переписані молитви, гімни й докладні коментарі про Святе Світло." }
    t[268551] = { name = "Сувій Роздумів", fen = "As the leader of the Illidari, you must make a choice for who will be your second-in-command.", fua = "Як проводир Іллідарі, ви маєте обрати, хто стане вашим заступником." }
    t[269578] = { name = "Залоза Отруйної Жаби-Древолаза", fen = "This organ is disturbingly warm, and excretes a mucus that numbs your skin on contact.", fua = "Цей орган тривожно теплий і виділяє слиз, від якого при дотику німіє шкіра." }
